window.CARDS=window.CARDS||{};CARDS["people-sudou-ken"]=[{"i":"sc-sudou-ken-y1v1-p37-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"hirata-yousuke sudou-ken","q":"sudo ken classroom day 1  rejection of self introductions class 1 d classroom after homeroom orientation  hirata attempts to facilitate class wide self introductions  student with fiery red dyed hair glares aggressively at hirata when prompted  tall  muscular  exudes an overpowering delinquent aura   what  are we a bunch of little kids or something  i don t need to introduce myself  people who want to do that can go ahead  just leave me out of it  when hirata bows apologetically and female classmates snap at sudo for being rude  sudo snaps right back  completely unfazed by class opinion   shut it  i don t care  i didn t come here to make friends  shoves his chair back and storms out of the classroom  triggering an exodus of several other rebellious students  including horikita  volatile  aggressive  solitary  deeply hostile to authority and forced camaraderie  refuses to play along with school social rituals  immediate clash with hirata s harmonious leadership  scorns hirata s polite approach","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p37-1\"><h3><span class=\"ttl\">Classroom Day 1: rejection of self-introductions<\/span><span class=\"meta\">Y1V1 · p.37–38<\/span><\/h3><p class=\"setup\">Class 1-D classroom after homeroom orientation. Hirata attempts to facilitate class-wide self-introductions.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What, are we a bunch of little kids or something? I don’t need to introduce myself. People who want to do that can go ahead. Just leave me out of it.”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\">“Shut it. I don’t care. I didn’t come here to make friends.”<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Student with fiery red dyed hair glares aggressively at Hirata when prompted. Tall, muscular, exudes an overpowering delinquent aura.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> When Hirata bows apologetically and female classmates snap at Sudō for being rude, Sudō snaps right back, completely unfazed by class opinion.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Shoves his chair back and storms out of the classroom, triggering an exodus of several other rebellious students (including Horikita).<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Volatile, aggressive, solitary, deeply hostile to authority and forced camaraderie; refuses to play along with school social rituals.<span class=\"pg\">p.37–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Immediate clash with Hirata&#x27;s harmonious leadership; scorns Hirata&#x27;s polite approach.<span class=\"pg\">p.37<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p46-1\">→ After: Convenience store: confrontation with second-years<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p46-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"ayanokouji-kiyotaka sudou-ken","q":"sudo ken convenience store  confrontation with second years campus convenience store on entrance ceremony afternoon  sudo is browsing instant ramen cups in the aisle  two second year upperclassmen deliberately bump into him  knocking his cup to the floor  fists clench  squares up against both upperclassmen instantly  utterly fearless despite being outnumbered   you got a lot of guts  asshole   yeah  so what   when asked what class he belongs to  when the second years learn he is in class d  they erupt into mocking laughter  label him a  defective  and walk away claiming they will let him off the hook because class d will  be in hell soon enough anyway   hey  don t run away  hey   ah  damn it  if those had been nice second year students  or cute girls  that would ve been great  instead  we had to deal with those annoying morons  completely ignores the spilled ramen cup on the floor  thrusts his hands in his pockets and storms off  oblivious to the two security cameras watching above the entrance  hot headed  physically combative  lacks foresight  leaves messes behind  completely unaware of institutional surveillance or the ominous meaning behind the  defective  stigma  unwitting beneficiary of ayanokoji s covert assistance  ak cleans up sudo s mess to prevent disciplinary fallout","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p46-1\"><h3><span class=\"ttl\">Convenience store: confrontation with second-years<\/span><span class=\"meta\">Y1V1 · p.46–51<\/span><\/h3><p class=\"setup\">Campus convenience store on entrance ceremony afternoon. Sudō is browsing instant ramen cups in the aisle. Two second-year upperclassmen deliberately bump into him, knocking his cup to the floor.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You got a lot of guts, asshole.”<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\">“Yeah, so what?” (when asked what class he belongs to)<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\">“Hey, don’t run away! Hey!”<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Fists clench; squares up against both upperclassmen instantly, utterly fearless despite being outnumbered.<span class=\"pg\">p.46–50<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> When the second-years learn he is in Class D, they erupt into mocking laughter, label him a &quot;defective&quot;, and walk away claiming they will let him off the hook because Class D will &quot;be in hell soon enough anyway.&quot;<span class=\"pg\">p.50–51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, damn it! If those had been nice second-year students, or cute girls, that would’ve been great. Instead, we had to deal with those annoying morons.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Completely ignores the spilled ramen cup on the floor; thrusts his hands in his pockets and storms off, oblivious to the two security cameras watching above the entrance.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Hot-headed, physically combative, lacks foresight; leaves messes behind; completely unaware of institutional surveillance or the ominous meaning behind the &quot;defective&quot; stigma.<span class=\"pg\">p.50–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Unwitting beneficiary of Ayanokōji&#x27;s covert assistance (AK cleans up Sudō&#x27;s mess to prevent disciplinary fallout).<span class=\"pg\">p.51–52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p37-1\">← Before: Classroom Day 1: rejection of self-introductions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p54-1\">→ After: Sleeping in class &amp; the basketball club commitment<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p54-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"ike-kanji ayanokouji-kiyotaka sudou-ken","q":"sudo ken sleeping in class   the basketball club commitment class 1 d classroom  day 2 morning  then gymnasium club fair  spends the vast majority of day 1 s orientation and academic classes fast asleep at his desk  setting an immediate reputation as a delinquent who refuses to pay attention while teachers show zero reaction  approaches ayanokoji at the gymnasium club fair alongside ike and yamauchi  forming a clear trio   yo  ayanokouji  you came  huh   yeah  i ve been playing basketball ever since elementary school  i thought i d join the team here  confirms he has already committed to joining the school s basketball club  welcomes ayanokoji into their informal circle as ike exchanges contact details for the boys  group chat  single minded dedication to basketball  his athletic ambition is his sole genuine anchor in high school  bonds with ike and yamauchi as fellow troublemakers  casual friendly acquaintance  includes him in the boys  network","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p54-1\"><h3><span class=\"ttl\">Sleeping in class &amp; the basketball club commitment<\/span><span class=\"meta\">Y1V1 · p.54, 68–71<\/span><\/h3><p class=\"setup\">Class 1-D classroom (Day 2 morning); then gymnasium club fair.<\/p><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yo, Ayanokouji. You came, huh?”<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\">“Yeah. I’ve been playing basketball ever since elementary school. I thought I’d join the team here.”<span class=\"pg\">p.68<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Spends the vast majority of Day 1&#x27;s orientation and academic classes fast asleep at his desk, setting an immediate reputation as a delinquent who refuses to pay attention while teachers show zero reaction.<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Approaches Ayanokōji at the gymnasium club fair alongside Ike and Yamauchi, forming a clear trio.<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Confirms he has already committed to joining the school&#x27;s basketball club. Welcomes Ayanokōji into their informal circle as Ike exchanges contact details for the boys&#x27; group chat.<span class=\"pg\">p.68–71<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Single-minded dedication to basketball; his athletic ambition is his sole genuine anchor in high school.<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Bonds with Ike and Yamauchi as fellow troublemakers.<span class=\"pg\">p.68<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Casual friendly acquaintance; includes him in the boys&#x27; network.<span class=\"pg\">p.68–71<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p46-1\">← Before: Convenience store: confrontation with second-years<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p73-1\">→ After: Disapproval of voyeurism &amp; the pool showdown with Kōenji<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p73-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"kouenji-rokusuke sudou-ken","q":"sudo ken disapproval of voyeurism   the pool showdown with koenji classroom 1 d  morning  then indoor swimming pool  visibly draws back in disgust when ike and sotomura propose taking voyeuristic photos and ranking the girls  breast sizes  showing a line of personal pride he won t cross  swims against hirata in the second boys  heat  uses aggressive  powerful strokes to win narrowly with a fast time of  approximately 26 seconds  shocked by koenji s staggering 23 22 second swim time  fiery competitive spirit ignites   i m not particularly interested in winning or losing but i don t like losing   i m fired up  races koenji head to head in the final heat  gives everything he has but is defeated by about five meters  fierce athletic competitor  hates losing to anyone  recognizes koenji s raw superiority while refusing to yield mentally  immediate athletic rivalry","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p73-1\"><h3><span class=\"ttl\">Disapproval of voyeurism &amp; the pool showdown with Kōenji<\/span><span class=\"meta\">Y1V1 · p.73, 85–88<\/span><\/h3><p class=\"setup\">Classroom 1-D (morning); then indoor swimming pool.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m not particularly interested in winning or losing…but I don’t like losing.”<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">“I’m fired up!”<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Visibly draws back in disgust when Ike and Sotomura propose taking voyeuristic photos and ranking the girls&#x27; breast sizes, showing a line of personal pride he won&#x27;t cross.<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Swims against Hirata in the second boys&#x27; heat; uses aggressive, powerful strokes to win narrowly with a fast time of **approximately 26 seconds**.<span class=\"pg\">p.85<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Shocked by Kōenji&#x27;s staggering 23.22-second swim time; fiery competitive spirit ignites.<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Races Kōenji head-to-head in the final heat; gives everything he has but is defeated by about five meters.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Fierce athletic competitor; hates losing to anyone; recognizes Kōenji&#x27;s raw superiority while refusing to yield mentally.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Immediate athletic rivalry.<span class=\"pg\">p.87–88<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p54-1\">← Before: Sleeping in class &amp; the basketball club commitment<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p102-1\">→ After: Classroom tardiness &amp; the Idiot Trio<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p102-1","v":"y1v1","y":1,"o":1,"k":"action","w":"ike-kanji sudou-ken","q":"sudo ken classroom tardiness   the idiot trio named in class 1 d s  idiot trio  with ike and yamauchi  classroom 1 d  third week of april  second period  math  slams through the classroom door halfway through math class  completely unapologetic about being late  slumps down in his seat with a massive yawn while the math teacher ignores him  formally branded alongside ike and yamauchi as part of class 1 d s notorious  idiot trio   san baka  shouts across the room during lessons making plans for lunch","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p102-1\"><h3><span class=\"ttl\">Classroom tardiness &amp; the Idiot Trio<\/span><span class=\"meta\">Y1V1 · p.102<\/span><\/h3><p class=\"setup\">Classroom 1-D, third week of April (second period, math).<\/p><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q action\">Slams through the classroom door halfway through math class, completely unapologetic about being late. Slumps down in his seat with a massive yawn while the math teacher ignores him.<span class=\"pg\">p.102<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Named in Class 1-D’s “Idiot Trio” with Ike and Yamauchi.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Formally branded alongside Ike and Yamauchi as part of Class 1-D&#x27;s notorious &quot;Idiot Trio&quot; (*San Baka*).<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Shouts across the room during lessons making plans for lunch.<span class=\"pg\">p.102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p73-1\">← Before: Disapproval of voyeurism &amp; the pool showdown with Kōenji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p127-1\">→ After: 14-point test crisis &amp; storming out on Hirata<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p127-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"hirata-yousuke sudou-ken","q":"sudo ken 14 point test crisis   storming out on hirata classroom 1 d  may 1st morning homeroom and subsequent class discussion  kicks the legs of his desk with a loud  furious thwack upon hearing class d is labeled defective failures   won t the other classes make fun of us  scores dead last in the class on the short diagnostic test with an abysmal  14 points   class average 65  severe academic deficiency  scores 14 100  landing directly on the immediate expulsion danger list for midterms  clicks his tongue and hangs his head in deep shame as chabashira confirms failing the midterm results in immediate expulsion  grumbles defensively when hirata calls him out by name from the podium   tch  what is it   huh  and why do you get to tell us what to do  besides  that s supposing our points will increase  if they don t change at all  then it s useless   i m still not convinced  besides  even if we get serious and work hard in class  our points won t necessarily go up   that s just your own selfish interpretation  besides  you don t know how to increase our points  try talking to me after you figure that out  rejects hirata s polite appeal with hostile defiance and storms out of the classroom   do whatever you want  it doesn t matter  just don t involve me in it  understand  prickly defensive pride  lashes out with verbal aggression when confronted with his own failings  flees uncomfortable social accountability  openly hostile toward hirata s moralizing leadership  refuses to be directed or lectured by him","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p127-1\"><h3><span class=\"ttl\">14-point test crisis &amp; storming out on Hirata<\/span><span class=\"meta\">Y1V1 · p.127–130, 134–135<\/span><\/h3><p class=\"setup\">Classroom 1-D, May 1st morning homeroom and subsequent class discussion.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Won’t the other classes make fun of us?”<span class=\"pg\">p.127<\/span><\/li><li class=\"q spoken\">“Tch, what is it?”<span class=\"pg\">p.134<\/span><\/li><li class=\"q spoken\">“Huh? And why do you get to tell us what to do? Besides, that’s supposing our points will increase. If they don’t change at all, then it’s useless.”<span class=\"pg\">p.134<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Kicks the legs of his desk with a loud, furious thwack upon hearing Class D is labeled defective failures.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Scores dead last in the class on the short diagnostic test with an abysmal **14 points** (class average 65).<span class=\"pg\">p.127–128<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Severe academic deficiency: scores 14/100, landing directly on the immediate expulsion danger list for midterms.<span class=\"pg\">p.128, 130<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Clicks his tongue and hangs his head in deep shame as Chabashira confirms failing the midterm results in immediate expulsion.<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Grumbles defensively when Hirata calls him out by name from the podium.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m still not convinced. Besides, even if we get serious and work hard in class, our points won’t necessarily go up.”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s just your own selfish interpretation. Besides, you don’t know how to increase our points. Try talking to me after you figure that out.”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Rejects Hirata’s polite appeal with hostile defiance and storms out of the classroom.<span class=\"pg\">p.134–135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do whatever you want. It doesn’t matter. Just don’t involve me in it. Understand?”<span class=\"pg\">p.134–135<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Prickly defensive pride; lashes out with verbal aggression when confronted with his own failings; flees uncomfortable social accountability.<span class=\"pg\">p.127, 134–135<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Openly hostile toward Hirata&#x27;s moralizing leadership; refuses to be directed or lectured by him.<span class=\"pg\">p.134–135<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p102-1\">← Before: Classroom tardiness &amp; the Idiot Trio<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p152-1\">→ After: Refusal, recruitment, &amp; the collar-grab<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p152-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"hirata-yousuke horikita-suzune kushida-kikyou sudou-ken","q":"sudo ken refusal  recruitment    the collar grab with ike and yamauchi  stays in his seat instead of joining hirata s announced study group  his rocky relationship with hirata since stomping all over the introduction game keeps him away  fresh from lunchtime basketball  sweating and short of breath  is directly invited by ayanokoji to horikita s after school study group   oh  that  i don t know  i ve never really studied seriously before   you serious  if the lessons are a pain in my ass  why would studying after class be any better  besides  i have club activities  so it s pointless  plus  you re going to be tutoring  your scores weren t great  either   horikita  i don t really know anything about her  sounds fishy  i ll pass  i ll be fine cramming for the test the night before  reverses course after kushida s personal recruitment and shows up at the library study group with ike  yamauchi  and okitani   scoring lower than thirty two means failing  do you fail if you get exactly thirty two points  though   look  i don t know how to study at all   so  what  we re like elementary school kids  throws his mechanical pencil onto the desk and quits before the session has even begun  provoking horikita s silent fury   stop  i m done  this isn t going to work   say whatever you want  academics will be useless in the future  anyway   i don t care if i can t solve this problem  studying s useless  aiming to become a pro basketball player will help me a lot more  gets in close and seizes horikita by the collar  kushida grabs his arm before anything happens  while horikita doesn t flinch  openly anti academic  convinced his basketball future makes studying pointless  explosive temper when humiliated  but stops short of striking a girl  relationship rocky ever since he stomped all over hirata s introduction game  pointedly ignores hirata s recruitment speech  direct confrontation  her merciless mockery of his abilities triggers the collar grab  she remains utterly unflinching  her recruitment gets him to the library  she physically restrains him when he loses his temper","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p152-1\"><h3><span class=\"ttl\">Refusal, recruitment, &amp; the collar-grab<\/span><span class=\"meta\">Y1V1 · p.152–157, 172–178<\/span><\/h3><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Oh, that. I don’t know. I’ve never really studied seriously before,”<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">“You serious? If the lessons are a pain in my ass, why would studying after class be any better? Besides, I have club activities, so it’s pointless. Plus, you’re going to be tutoring? Your scores weren’t great, either.”<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">“Horikita? I don’t really know anything about her. Sounds fishy; I’ll pass. I’ll be fine cramming for the test the night before.”<span class=\"pg\">p.157<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> With Ike and Yamauchi, stays in his seat instead of joining Hirata&#x27;s announced study group; his rocky relationship with Hirata since stomping all over the introduction game keeps him away.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Fresh from lunchtime basketball, sweating and short of breath, is directly invited by Ayanokōji to Horikita&#x27;s after-school study group.<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Reverses course after Kushida&#x27;s personal recruitment and shows up at the library study group with Ike, Yamauchi, and Okitani.<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Scoring lower than thirty-two means failing. Do you fail if you get exactly thirty-two points, though?”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Look, I don’t know how to study at all,”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what, we’re like elementary school kids?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Throws his mechanical pencil onto the desk and quits before the session has even begun, provoking Horikita&#x27;s silent fury.<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stop. I’m done. This isn’t going to work.”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Say whatever you want. Academics will be useless in the future, anyway.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t care if I can’t solve this problem. Studying’s useless. Aiming to become a pro basketball player will help me a lot more.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Gets in close and seizes Horikita by the collar; Kushida grabs his arm before anything happens, while Horikita doesn&#x27;t flinch.<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Openly anti-academic; convinced his basketball future makes studying pointless; explosive temper when humiliated, but stops short of striking a girl.<span class=\"pg\">p.157, 174–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Relationship rocky ever since he stomped all over Hirata&#x27;s introduction game; pointedly ignores Hirata&#x27;s recruitment speech.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Direct confrontation: her merciless mockery of his abilities triggers the collar-grab; she remains utterly unflinching.<span class=\"pg\">p.174–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Her recruitment gets him to the library; she physically restrains him when he loses his temper.<span class=\"pg\">p.172, 177<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p127-1\">← Before: 14-point test crisis &amp; storming out on Hirata<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p207-1\">→ After: The apology standoff, the date bribe &amp; turning Class C<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p207-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"horikita-suzune kushida-kikyou ichinose-honami sudou-ken","q":"sudo ken the apology standoff  the date bribe   turning class c arrives after kushida s  honey trap  invitation  glares at horikita and refuses the rematch on pride grounds  demanding a genuine apology first   drop it  or i ll beat the crap out of you  i m busy with basketball now  anyway  i ll be just fine if i cram before the test   well  i i don t want any of your stupid charity  i haven t forgotten the bullshit way you spoke to me the other day  if you want me to join  i want an apology first  a completely honest one   you really want to get up to class a  then  even if that means inviting someone you hate  like me   i m busy with basketball  the others on the team never take study breaks  not even before a big test  i can t fall behind everyone else by doing something as boring as studying  shown horikita s notebook schedule  scoffs  what kind of sorcery  but stays to listen  turns to leave for good   until ayanokoji s kushida date stunt reframes the stakes   a date  huh  that doesn t sound too bad  jeez  guess i don t have a choice  all right  i ll join   voice small  not turning around   the group is saved  studies seriously in class for the first time  nods off repeatedly but fights sleep for his pro basketball dream  narration  worthy of praise   so what  what s the big deal if we re in class d  do you have a problem with that   fires back at yamawaki s taunts   we don t have any points to lose   as he seizes yamawaki by the collar  ready to strike despite point risks  released only when ichinose s logical intervention breaks the standoff  pivots fully  bows to horikita and offers to suspend club activities for the final week   inspired by anger at chabashira s test material blunder and class c s taunts   horikita  i know i ve been difficult  but i m counting on you     starting tomorrow i ll take a break from club activities  will that work   yeah  i mean  i m pissed at our homeroom teacher and those jerks in class c now  too   studying is a lot of work  isn t it   grinning as he pats her shoulder   immediately rebuked  pride governed but persuadable  insults  stakes  and rage each move him where appeals to duty don t  converts antagonism into study fuel  from apology demand to bowing pledge   her blunt honesty plus the class c humiliation finally earns his cooperation  her honey trap invitation brings him back to the table  physically checked by her  lets go when she threatens a report","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p207-1\"><h3><span class=\"ttl\">The apology standoff, the date bribe &amp; turning Class C<\/span><span class=\"meta\">Y1V1 · p.207–211, 219–221, 227<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Drop it, or I’ll beat the crap out of you. I’m busy with basketball now, anyway. I’ll be just fine if I cram before the test.”<span class=\"pg\">p.207<\/span><\/li><li class=\"q spoken\">“Well, I…I don’t want any of your stupid charity. I haven’t forgotten the bullshit way you spoke to me the other day. If you want me to join, I want an apology first. A completely honest one,”<span class=\"pg\">p.207<\/span><\/li><li class=\"q spoken\">“You really want to get up to Class A, then? Even if that means inviting someone you hate, like me?”<span class=\"pg\">p.207<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Arrives after Kushida&#x27;s &quot;honey trap&quot; invitation; glares at Horikita and refuses the rematch on pride grounds, demanding a genuine apology first.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m busy with basketball. The others on the team never take study breaks, not even before a big test. I can’t fall behind everyone else by doing something as boring as studying.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Shown Horikita&#x27;s notebook schedule; scoffs (&quot;What kind of sorcery…&quot;) but stays to listen.<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Turns to leave for good — until Ayanokōji&#x27;s Kushida-date stunt reframes the stakes.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A date, huh? That doesn’t sound too bad. Jeez, guess I don’t have a choice. All right, I’ll join,” (voice small, not turning around — the group is saved)<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Studies seriously in class for the first time; nods off repeatedly but fights sleep for his pro-basketball dream (narration: worthy of praise).<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what? What’s the big deal if we’re in Class D? Do you have a problem with that?” (fires back at Yamawaki&#x27;s taunts)<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We don’t have any points to lose!” (as he seizes Yamawaki by the collar, ready to strike despite point risks)<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Released only when Ichinose&#x27;s logical intervention breaks the standoff.<span class=\"pg\">p.221–222<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Pivots fully: bows to Horikita and offers to suspend club activities for the final week — inspired by anger at Chabashira&#x27;s test-material blunder and Class C&#x27;s taunts.<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Horikita. I know I’ve been difficult, but I’m counting on you.” … “Starting tomorrow…I’ll take a break from club activities. Will that work?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. I mean, I’m pissed at our homeroom teacher and those jerks in Class C now, too.”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Studying is a lot of work, isn’t it?” (grinning as he pats her shoulder — immediately rebuked)<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Pride-governed but persuadable: insults, stakes, and rage each move him where appeals to duty don&#x27;t; converts antagonism into study fuel.<span class=\"pg\">p.207–227<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> From apology demand to bowing pledge — her blunt honesty plus the Class C humiliation finally earns his cooperation.<span class=\"pg\">p.207, 227<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Her honey-trap invitation brings him back to the table.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Physically checked by her; lets go when she threatens a report.<span class=\"pg\">p.222<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p152-1\">← Before: Refusal, recruitment, &amp; the collar-grab<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p236-1\">→ After: The English gap, Horikita&#x27;s apology &amp; the crush<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p236-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken the english gap  horikita s apology   the crush happily accepts the old test sheets  yeah  thanks  you really helped me out  exam break  the only study group member left sullen   admits he fell asleep partway through the english old test review  first time seeing the material  ten minutes to cram   everything but english  i fell asleep partway through   damn  i can t get any of these answers to stick in my head   unlike japanese  i don t know the basics of english  these letters look like some kind of magic spell or something  memorizing it ll take time  during the english test  visibly struggles   stops writing and whacks his pen against his head  nobody can help him  after the tests  on the verge of losing his cool  flogs himself for sleeping   i don t know  i did everything i could  but i have no idea how well i did     damn it  why did i fall asleep  receives horikita s praise and her researched apology for mocking his pro basketball dream   stunned speechless  then delivers the chapter s closing confession   what is this  are you trying to comfort me   o oh  no  i  i think i might be in love with horikita  honest effort under adversity  pride replaced by gratitude   the apology converts hostility into infatuation overnight  full conversion  her genuine acknowledgment of his effort   dream apology produces an open  i might be in love with horikita  declaration to the group","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p236-1\"><h3><span class=\"ttl\">The English gap, Horikita&#x27;s apology &amp; the crush<\/span><span class=\"meta\">Y1V1 · p.236–245<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Everything but English. I fell asleep partway through.”<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\">“Damn, I can’t get any of these answers to stick in my head,”<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\">“Unlike Japanese, I don’t know the basics of English. These letters look like some kind of magic spell or something. Memorizing it’ll take time.”<span class=\"pg\">p.242<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Happily accepts the old-test sheets (&quot;Yeah. Thanks, you really helped me out.&quot;).<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Exam break: the only study-group member left sullen — admits he fell asleep partway through the English old-test review; first time seeing the material, ten minutes to cram.<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> During the English test, visibly struggles — stops writing and whacks his pen against his head; nobody can help him.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After the tests: on the verge of losing his cool; flogs himself for sleeping.<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t know… I did everything I could, but I have no idea how well I did…” / “Damn it, why did I fall asleep?”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Receives Horikita&#x27;s praise and her researched apology for mocking his pro-basketball dream — stunned speechless, then delivers the chapter&#x27;s closing confession.<span class=\"pg\">p.244–245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is this? Are you trying to comfort me?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “O-oh, no… I… I think I might be in love with Horikita…”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Honest effort under adversity; pride replaced by gratitude — the apology converts hostility into infatuation overnight.<span class=\"pg\">p.241–245<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Full conversion: her genuine acknowledgment of his effort + dream apology produces an open &quot;I might be in love with Horikita&quot; declaration to the group.<span class=\"pg\">p.244–245<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p207-1\">← Before: The apology standoff, the date bribe &amp; turning Class C<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p246-1\">→ After: The red line &amp; learning who saved him<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p246-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken the red line   learning who saved him scores 60 in four subjects and 39 in english   leaps up celebrating  yes  with ike and yamauchi  no red in sight  explodes when chabashira draws the red line above his name  pass mark was 40  not 32   he was one point short   huh  you re lying  right  don t give me that crap  why did i fail   don t screw with me  i got thirty two points  i passed   f forty  you never told us about this  i won t accept it   no way  so  does that mean i m going to be expelled  watches horikita s counter trap unfold and is the first to grasp what her 51 point english score means   horikita     you really   realizing she botched her own exam to lower the class average and save him   why  you said that you hated me  expulsion quietly cancelled after ak and horikita buy a test point for 100 000 points  publicly passionate  celebrates loudly  rages at injustice  and is visibly converted by discovering a sacrifice made for him  learns she tanked her own grade for him   the pivot from  i hate you  to the p 245 confession gains its cause","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p246-1\"><h3><span class=\"ttl\">The red line &amp; learning who saved him<\/span><span class=\"meta\">Y1V1 · p.246–250<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Huh? You’re lying, right? Don’t give me that crap! Why did I fail?”<span class=\"pg\">p.247<\/span><\/li><li class=\"q spoken\">“Don’t screw with me! I got thirty-two points! I passed!”<span class=\"pg\">p.247<\/span><\/li><li class=\"q spoken\">“F-forty?! You never told us about this! I won’t accept it!”<span class=\"pg\">p.247<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Scores 60 in four subjects and 39 in English — leaps up celebrating (&quot;Yes!&quot;) with Ike and Yamauchi, no red in sight.<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Explodes when Chabashira draws the red line above his name: pass mark was 40, not 32 — he was one point short.<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way… So… Does that mean I’m going to be expelled?”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Watches Horikita&#x27;s counter-trap unfold and is the first to grasp what her 51-point English score means.<span class=\"pg\">p.249–250<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Horikita…” / “You really—” (realizing she botched her own exam to lower the class average and save him)<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why? You said that you hated me,”<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Expulsion quietly cancelled after AK and Horikita buy a test point for 100,000 points.<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Publicly passionate: celebrates loudly, rages at injustice, and is visibly converted by discovering a sacrifice made for him.<span class=\"pg\">p.246–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Learns she tanked her own grade for him — the pivot from &quot;I hate you&quot; to the p.245 confession gains its cause.<span class=\"pg\">p.249–250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p236-1\">← Before: The English gap, Horikita&#x27;s apology &amp; the crush<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p256-1\">→ After: Reformed at the victory party<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v1-p256-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken reformed at the victory party guest of honor at the no one expelled celebration in ak s room   well  i guess  but you re a surprisingly good person  horikita   openly  his antagonism fully ended since her apology   narration   people could change   well  if horikita asked me to help  i would  i guess   hides embarrassment while enlisting   grr  i just thought i d try to be nice  is all  and   you re a really annoying girl     you are not cute at all  lady   his new bickering frequency with horikita   no anger behind it  instantly headlocks ike for teasing the horikita exchange   play violence  not fury  if you say anything else  i m going to strangle you   well  if it comes down to physical ability  leave it to me  i have serious basketball and fighting skills  completed conversion  from collar grab attacker to teasing  loyal group muscle  temper now expressed as horseplay  calls her a  surprisingly good person  and volunteers to follow her   the p 245 confession matured into partnership banter","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v1-p256-1\"><h3><span class=\"ttl\">Reformed at the victory party<\/span><span class=\"meta\">Y1V1 · p.256–262<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Well, I guess, but…you’re a surprisingly good person, Horikita,” (openly; his antagonism fully ended since her apology — narration: &quot;people could change&quot;)<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\">“Well, if Horikita asked me to help, I would. I guess.” (hides embarrassment while enlisting)<span class=\"pg\">p.261<\/span><\/li><li class=\"q spoken\">“Grr. I just thought I’d try to be nice, is all, and—”<span class=\"pg\">p.261<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Guest of honor at the no-one-expelled celebration in AK&#x27;s room.<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re a really annoying girl,” / “You are not cute at all, lady.” (his new bickering frequency with Horikita — no anger behind it)<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Instantly headlocks Ike for teasing the Horikita exchange — play violence, not fury (&quot;If you say anything else, I’m going to strangle you!&quot;).<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, if it comes down to physical ability, leave it to me. I have serious basketball and fighting skills.”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Completed conversion: from collar-grab attacker to teasing, loyal group muscle; temper now expressed as horseplay.<span class=\"pg\">p.257–262<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Calls her a &quot;surprisingly good person&quot; and volunteers to follow her — the p.245 confession matured into partnership banter.<span class=\"pg\">p.257, 261<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v1-p246-1\">← Before: The red line &amp; learning who saved him<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p12-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 2 opening  one punches three class c boys  finishes the fight post fight tableau seen through sakura s eyes  three boys on the floor  sudou standing over them  right fist bloody   it was an entirely one sided ordeal   he he  so  do you really think that this is the end of it  sudou   one of the beaten class c boys taunts from the floor   speaker unnamed   do you wanna make me laugh  you re in the sorriest state possible  you want to go for another round  huh  next time i won t hold back  grabs the taunter s collar and hauls him face to face   sudou looked as though he was going to kill and then devour his opponent  which was so overwhelming that the defeated boy looked away   are you scared  did you really think you d beat me if you had more people   what a waste of time  tiring me out after practice  give me a break   nothing s more pathetic than a sore loser  no matter how many times you come at me  you won t win  leaves like the winners  corner doesn t matter   dropped the student  picked up his bag  and then turned and walked away as if the defeated three completely disinterested him   is someone there   senses sakura s movement  misses her by two seconds   he never learns there was a witness","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p12-1\"><h3><span class=\"ttl\">Ch.2 opening: one-punches three Class C boys, finishes the fight<\/span><span class=\"meta\">Y1V2 · p.12–13<\/span><\/h3><p class=\"setup\">Post-fight tableau seen through Sakura&#x27;s eyes: three boys on the floor, Sudou standing over them, right fist bloody; &quot;It was an entirely one-sided ordeal.&quot;<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;He he, so. Do you really think that this is the end of it, Sudou?&quot; (one of the beaten Class C boys taunts from the floor — speaker unnamed)<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\">&quot;Do you wanna make me laugh? You’re in the sorriest state possible. You want to go for another round, huh? Next time I won’t hold back.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\">&quot;Are you scared? Did you really think you’d beat me if you had more people?&quot;<span class=\"pg\">p.13<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Grabs the taunter&#x27;s collar and hauls him face-to-face; &quot;Sudou looked as though he was going to kill and then devour his opponent, which was so overwhelming that the defeated boy looked away.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What a waste of time. Tiring me out after practice. Give me a break,&quot;<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Nothing’s more pathetic than a sore loser. No matter how many times you come at me, you won’t win.&quot;<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Leaves like the winners&#x27; corner doesn&#x27;t matter: &quot;dropped the student, picked up his bag, and then turned and walked away as if the defeated three completely disinterested him.&quot;<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Is someone there?&quot; (senses Sakura&#x27;s movement; misses her by two seconds — he never learns there was a witness)<span class=\"pg\">p.13<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p22-1\">→ After: Ch.2 §2.3: hauled to the faculty room<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p22-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 2  2 3  hauled to the faculty room tries to bolt to basketball practice when chabashira calls him  lazily flashes his sports uniform  only follows her after her consequence threat  clicking his tongue   huh  what do you want with me  i ve got basketball practice now   what  will this be over quickly  a classmate s mutter sums his reputation   i thought that he might have changed  but i guess sudou s the same as ever  wouldn t it have been better if he just got kicked out","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p22-1\"><h3><span class=\"ttl\">Ch.2 §2.3: hauled to the faculty room<\/span><span class=\"meta\">Y1V2 · p.22–23<\/span><\/h3><p class=\"setup\">Tries to bolt to basketball practice when Chabashira calls him; lazily flashes his sports uniform; only follows her after her consequence threat, clicking his tongue.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Huh? What do you want with me? I’ve got basketball practice now.&quot;<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\">&quot;What? Will this be over quickly?&quot;<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Backstory<\/span> A classmate&#x27;s mutter sums his reputation: &quot;I thought that he might have changed, but I guess Sudou’s the same as ever. Wouldn’t it have been better if he just got kicked out?&quot;<span class=\"pg\">p.22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p12-1\">← Before: Ch.2 opening: one-punches three Class C boys, finishes the fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p27-1\">→ After: Ch.2 §2.4: confesses the fight to AK + Kushida, begs for secrecy<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p27-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ayanokouji-kiyotaka kushida-kikyou hirata-yousuke ike-kanji sudou-ken","q":"sudo ken ch 2  2 4  confesses the fight to ak   kushida  begs for secrecy bursts into ayanokoji s locked room  duplicate keycard made by ike s group  with a beet red face  he may be suspended   save me  ayanokouji   this the room where our group meets  isn t it  ike and the rest of us made duplicate keys  didn t you know that  everyone else in the group has a key  too   huh  why  i bought this with my own points  it s mine   refusing to surrender the cloned key   i can t ask them  they re stupid   why not ike yamauchi   buy some carpet  will ya  my butt hurts   thuds onto ak s bare floor   you know how our homeroom teacher called me today  well  it s  uh  the truth is i may be suspended  for a long time  actually   it s probably worse than you re thinking   to tell you the truth  i beat up some kids from class c yesterday  then  i got suspended  the suspension is probably my punishment   just so you know  it wasn t my fault  okay  the jerks in class c started it and tried to pick a fight with me  i just responded to the situation and turned the tables on them  then they said that i started the fight  they re a bunch of liars   sorry  i guess i just kind of skipped to the end and left a lot out   i was talking with the club advisor about being a regular for the summer tournament   well  nothing s set in stone yet  it s just a possibility for now   yeah  i suppose  actually  i was the only first year student nominated to be a regular player  still  it s not like it s definite  anyway  when i was on my way back to the dorm  komiya and kondou  who re in the basketball club with me  called me over to the special building  they said they wanted to talk to me about something  i could ve just ignored them  but i mean  i occasionally talk to those two guys during basketball  i thought it d be better to just hear them out  so of course  i went to meet with them  right  then  there was this ishizaki guy there  waiting for me  he s komiya and kondou s friend  they said that they couldn t stand that someone like me from class d had been chosen as a regular  they threatened me  and said to quit basketball or there d be a lot of pain in my future  i refused to quit  i beat them up  and now i m here   right  i seriously don t get this  i can t believe that teacher  either   they said they would give me until next tuesday to come up with proof  if i can t do that  they ll say i m at fault and i ll be suspended until summer  on top of that  the whole class will lose points  too   what do you mean  you wonder  you re not doubting me  are you   huh  why  it was legitimate self defense  wasn t it  huh   smacks the table at ak s verdict   i m sorry  i just got a little mad   instantly apologizes when kushida flinches   i i don t understand  though  i was up against three people  three  that seems plenty dangerous   i still don t get it  i m the victim here  being suspended isn t some kind of joke  if i m punished for this  forget being a regular player  i won t even be able to play in the tournament   those guys aren t idiots  they won t be honest  goddamn it  i won t ever forgive them  those damn nobodies   snaps ak s ballpoint pen in two   there might be something  though  this might just be a misunderstanding on my part  but when i was fighting those guys i felt something odd  like someone was nearby  watching me   yeah  i think so  i don t have proof anyone was there  though   what should i do   head in hands   this might sound kind of shameless  but can you guys not tell anyone about this   if word gets out  it ll definitely get around to the basketball team  i don t want that to happen  you understand  right   please understand  ayanokouji  if i can t play basketball  i have nothing   grips ak s shoulders   but  if i dump this on you guys   all right  i know this is a bother for you guys  but i ll leave it to you   well  we ll head back to our rooms  i m sorry for barging in here  basketball is his entire identity  keeps the secret circle tiny  ak   kushida  not even horikita hirata  still won t give up the cloned key  apology reflex toward girls  kushida s stiffened shoulders  comes to ak before anyone else   trust earned via the midterm point purchase  ak grudgingly keeps hosting him  comfortable venting in front of her  softens instantly when she s startled  still hates hirata  per ak   sudou hates hirata  so that makes horikita the obvious choice  rates ike yamauchi as useless for advice  they re stupid  yet keeps using their cloned key club","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p27-1\"><h3><span class=\"ttl\">Ch.2 §2.4: confesses the fight to AK + Kushida, begs for secrecy<\/span><span class=\"meta\">Y1V2 · p.27–38<\/span><\/h3><p class=\"setup\">Bursts into Ayanokōji&#x27;s locked room (duplicate keycard made by Ike&#x27;s group) with a beet-red face: he may be suspended.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Save me, Ayanokouji!&quot;<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\">&quot;This the room where our group meets, isn’t it? Ike and the rest of us made duplicate keys. Didn’t you know that? Everyone else in the group has a key, too.&quot;<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\">&quot;Huh? Why? I bought this with my own points. It’s mine.&quot; (refusing to surrender the cloned key)<span class=\"pg\">p.27<\/span><\/li><\/ul><details class=\"more\"><summary>32 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I can’t ask them. They’re stupid.&quot; (why not Ike/Yamauchi)<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Buy some carpet, will ya? My butt hurts,&quot; (thuds onto AK&#x27;s bare floor)<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You know how our homeroom teacher called me today? Well, it’s… Uh… The truth is…I may be suspended. For a long time, actually.&quot;<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It’s probably worse than you’re thinking…&quot;<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;To tell you the truth, I beat up some kids from Class C yesterday. Then, I got suspended. The suspension is probably my punishment.&quot;<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Just so you know, it wasn’t my fault, okay? The jerks in Class C started it and tried to pick a fight with me. I just responded to the situation and turned the tables on them. Then they said that I started the fight. They’re a bunch of liars.&quot;<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Sorry, I guess I just kind of skipped to the end and left a lot out.&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I was talking with the club advisor about being a regular for the summer tournament.&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, nothing’s set in stone yet. It’s just a possibility for now.&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I suppose. Actually, I was the only first-year student nominated to be a regular player. Still, it’s not like it’s definite. Anyway, when I was on my way back to the dorm, Komiya and Kondou, who’re in the basketball club with me, called me over to the special building. They said they wanted to talk to me about something. I could’ve just ignored them, but I mean, I occasionally talk to those two guys during basketball. I thought it’d be better to just hear them out. So of course, I went to meet with them, right? Then, there was this Ishizaki guy there, waiting for me. He’s Komiya and Kondou’s friend. They said that they couldn’t stand that someone like me from Class D had been chosen as a regular. They threatened me, and said to quit basketball or there’d be a lot of pain in my future. I refused to quit, I beat them up, and now I’m here.&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Right? I seriously don’t get this. I can’t believe that teacher, either!&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;They said they would give me until next Tuesday to come up with proof. If I can’t do that, they’ll say I’m at fault and I’ll be suspended until summer. On top of that, the whole class will lose points, too.&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What do you mean, you wonder? You’re not doubting me, are you?&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Huh? Why? It was legitimate self-defense, wasn’t it? Huh?!&quot; (smacks the table at AK&#x27;s verdict)<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’m sorry, I just got a little mad.&quot; (instantly apologizes when Kushida flinches)<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I-I don’t understand, though. I was up against three people. Three! That seems plenty dangerous.&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I still don’t get it. I’m the victim here! Being suspended isn’t some kind of joke! If I’m punished for this, forget being a regular player. I won’t even be able to play in the tournament!&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Those guys aren’t idiots. They won’t be honest. Goddamn it, I won’t ever forgive them! Those damn nobodies!&quot; (snaps AK&#x27;s ballpoint pen in two)<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There might be something, though. This might just be a misunderstanding on my part, but when I was fighting those guys I felt something…odd. Like someone was nearby, watching me.&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I think so. I don’t have proof anyone was there, though.&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What should I do?&quot; (head in hands)<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;This might sound kind of shameless, but…can you guys not tell anyone about this?&quot;<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If word gets out, it’ll definitely get around to the basketball team. I don’t want that to happen. You understand, right?&quot;<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Please understand, Ayanokouji. If I can’t play basketball, I have nothing,&quot; (grips AK&#x27;s shoulders)<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But, if I dump this on you guys—&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;All right. I know this is a bother for you guys, but I’ll leave it to you.&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, we’ll head back to our rooms. I’m sorry for barging in here.&quot;<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Basketball is his entire identity; keeps the secret circle tiny (AK + Kushida, not even Horikita/Hirata); still won&#x27;t give up the cloned key; apology reflex toward girls (Kushida&#x27;s stiffened shoulders).<span class=\"pg\">p.27–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Comes to AK before anyone else — trust earned via the midterm point purchase; AK grudgingly keeps hosting him.<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Comfortable venting in front of her; softens instantly when she&#x27;s startled.<span class=\"pg\">p.29–36<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Still hates Hirata (per AK: &quot;Sudou hates Hirata, so that makes Horikita the obvious choice.&quot;).<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Rates Ike/Yamauchi as useless for advice (&quot;They’re stupid.&quot;) yet keeps using their cloned-key club.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p22-1\">← Before: Ch.2 §2.3: hauled to the faculty room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p40-1\">→ After: Ch.3 open: his defence collapses in front of the class<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p40-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 3 open  his defence collapses in front of the class  it wasn t my fault  it was self defense  self defense  i tell you  he shouts it  as he shouldered his classmates  icy glares    the class is already against him before chabashira finishes   what evidence  i don t have any   all i know is that i m innocent  if anything  i ought to receive a settlement for my trouble   looks that way   his own answer to  there are no witnesses in this class   when chabashira sensei cast a doubtful look at sudou  he glanced downward   huh  you re telling everyone   damn it  ak s verdict on the strategy   sudou s plan had already fallen apart  the secrecy he begged for two nights earlier dies the moment the school canvasses every class for a witness  he leaves with chabashira immediately   chabashira sensei left  and sudou followed right after her  he probably realized that if he stayed in the classroom  he d lose his temper with someone","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p40-1\"><h3><span class=\"ttl\">Ch.3 open: his defence collapses in front of the class<\/span><span class=\"meta\">Y1V2 · p.40–41<\/span><\/h3><p class=\"setup\">He shouts it &quot;as he shouldered his classmates’ icy glares&quot; — the class is already against him before Chabashira finishes. &quot;When Chabashira-sensei cast a doubtful look at Sudou, he glanced downward.&quot; He leaves with Chabashira immediately: &quot;Chabashira-sensei left, and Sudou followed right after her. He probably realized that if he stayed in the classroom, he’d lose his temper with someone.&quot;<\/p><ul class=\"lines\"><li class=\"q spoken\">“It wasn’t my fault! It was self-defense! Self-defense, I tell you!”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\">“What evidence? I don’t have any.”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\">“All I know is that I’m innocent. If anything, I ought to receive a settlement for my trouble.”<span class=\"pg\">p.40<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Looks that way,” (his own answer to &quot;there are no witnesses in this class&quot;)<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Huh?! You’re telling everyone?!”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Damn it!”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> AK&#x27;s verdict on the strategy: &quot;Sudou’s plan had already fallen apart.&quot; The secrecy he begged for two nights earlier dies the moment the school canvasses every class for a witness.<span class=\"pg\">p.41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p27-1\">← Before: Ch.2 §2.4: confesses the fight to AK + Kushida, begs for secrecy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p42-1\">→ After: Ch.3 §3.1: the class&#x27;s own memory of him is the case against him<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p42-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 3  3 1  the class s own memory of him is the case against him classmates answer kushida s appeal with their own sightings  speakers unnamed   i saw him grab some kid by the collar just because they bumped into each other in the hallway     i saw him cut in line in the cafeteria and lash out when someone tried to tell him that wasn t okay  yamauchi s public counter testimony  which turns the room  that sudou  lied so he could justify what he did  that  he talked about beating up kids all the time in junior high  he even told us how much fun it was to beat people up  in the cafeteria he pleads to horikita in flat  external terms   sudou spoke to horikita with indifference  almost as if he were describing someone else s problems   i m sorry  horikita  i ve caused trouble for you again  but it really wasn t my fault this time  all i did was blow up those class c jerks  plans   wait  you might be right about that  but i m not the one at fault here  those guys picked a fight with me  what part of that is my fault   what s trivial about it  it makes all the difference  i didn t do anything wrong   so you re not gonna help  i thought we were friends   what the hell is her deal  goddamn it  his temper performs the argument against him in real time   unable to direct his rage anywhere else  sudou slammed his fists on the cafeteria table  spilling a nearby student s miso soup  the student glared  but when he saw how scary sudou looked  he remained silent  he assumes the friendship she refused to name  her answer   that she has  never once considered you a friend    is the first time the class hears her draw that line out loud","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p42-1\"><h3><span class=\"ttl\">Ch.3 §3.1: the class&#x27;s own memory of him is the case against him<\/span><span class=\"meta\">Y1V2 · p.42–45<\/span><\/h3><p class=\"setup\">Classmates answer Kushida&#x27;s appeal with their own sightings, speakers unnamed: &quot;I saw him grab some kid by the collar just because they bumped into each other in the hallway.&quot; / &quot;I saw him cut in line in the cafeteria and lash out when someone tried to tell him that wasn’t okay.&quot; In the cafeteria he pleads to Horikita in flat, external terms: &quot;Sudou spoke to Horikita with indifference, almost as if he were describing someone else’s problems.&quot;<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m sorry, Horikita. I’ve caused trouble for you again. But it really wasn’t my fault this time. All I did was blow up those Class C jerks’ plans.”<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\">“Wait. You might be right about that, but I’m not the one at fault here! Those guys picked a fight with me! What part of that is my fault?”<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\">“What’s trivial about it? It makes all the difference! I didn’t do anything wrong!”<span class=\"pg\">p.44<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Backstory<\/span> Yamauchi&#x27;s public counter-testimony, which turns the room: that Sudou &quot;lied so he could justify what he did&quot;, that &quot;He talked about beating up kids all the time in junior high. He even told us how much fun it was to beat people up.&quot;<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re not gonna help? I thought we were friends!”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell is her deal?! Goddamn it!”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> His temper performs the argument against him in real time: &quot;Unable to direct his rage anywhere else, Sudou slammed his fists on the cafeteria table, spilling a nearby student’s miso soup. The student glared, but when he saw how scary Sudou looked, he remained silent.&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He assumes the friendship she refused to name; her answer — that she has &quot;never once considered you a friend&quot; — is the first time the class hears her draw that line out loud.<span class=\"pg\">p.44–45<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p40-1\">← Before: Ch.3 open: his defence collapses in front of the class<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p46-1\">→ After: Ch.3 §3.1: he cannot accept that her refusal has a reason<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p46-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"kushida-kikyou sudou-ken","q":"sudo ken ch 3  3 1  he cannot accept that her refusal has a reason  i don t really want to think about it  but i guess it might be true   is it because she hates sudou  i mean  she just said she didn t consider him a friend    read as kushida s line to the group  on sudou s behalf  the text attributes neither to a named speaker   what s trivial about it      see p 44  he returns to the same refusal to examine his own part   what idea  to toss me out like the trash   so what  you don t have a reason  ak s diagnosis  which horikita states herself one page later  he will not accept a reason for the refusal  only a verdict   since horikita was definitely on his mind  he probably wasn t too pleased about her rejection  he accepts her defence of him and never credits it  his own attitude flip in this chapter comes from ike being recruited by her  not from him changing anything","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p46-1\"><h3><span class=\"ttl\">Ch.3 §3.1: he cannot accept that her refusal has a reason<\/span><span class=\"meta\">Y1V2 · p.46–47<\/span><\/h3><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I don’t really want to think about it, but I guess it might be true.”<span class=\"pg\">p.46<\/span><\/li><li class=\"q spoken\">“Is it because she hates Sudou? I mean, she just said she didn’t consider him a friend.” — read as Kushida&#x27;s line to the group, on Sudou&#x27;s behalf; the text attributes neither to a named speaker.<span class=\"pg\">p.46<\/span><\/li><li class=\"q spoken\">“What’s trivial about it? ...” — see p.44; he returns to the same refusal to examine his own part.<span class=\"pg\">p.46<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What idea? To toss me out like the trash?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what? You don’t have a reason?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> AK&#x27;s diagnosis, which Horikita states herself one page later: he will not accept a reason for the refusal, only a verdict. &quot;Since Horikita was definitely on his mind, he probably wasn’t too pleased about her rejection.&quot;<span class=\"pg\">p.46–47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> He accepts her defence of him and never credits it; his own attitude flip in this chapter comes from Ike being recruited by her, not from him changing anything.<span class=\"pg\">p.44<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p42-1\">← Before: Ch.3 §3.1: the class&#x27;s own memory of him is the case against him<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p51-1\">→ After: Ch.3 §3.1: the Horikita fantasy, stated in front of the class<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p51-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ike-kanji sudou-ken","q":"sudo ken ch 3  3 1  the horikita fantasy  stated in front of the class  just to be sure  there s really nothing between you and horikita   okay  fine then  i guess i misunderstood  i thought you were clinging to her too much  that d be a bother for horikita   you guys don t know anything  horikita is hands down better than kushida  anyway   i mean  if it was any other guy  she d probably turn them down  but if you were her boyfriend  then it d be okay  right  then she d show you a secret side that no one else gets to see  ak s frame on the speech  he  crossed his arms and nodded  boasting about his personal preferences    he reads horikita s coldness as a stage of courtship rather than a refusal  which is exactly the non recognition she named on p 45  the three of them run a rivalry about who gets a girlfriend while his own suspension clock runs down  yamauchi s  but the horikita of your dreams seems to have tossed you aside  sudou  lands  and he answers  well  i guess so  damn it  now i feel all depressed","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p51-1\"><h3><span class=\"ttl\">Ch.3 §3.1: the Horikita fantasy, stated in front of the class<\/span><span class=\"meta\">Y1V2 · p.51<\/span><\/h3><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Just to be sure, there’s really nothing between you and Horikita?”<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\">“Okay, fine then. I guess I misunderstood. I thought you were clinging to her too much. That’d be a bother for Horikita.”<span class=\"pg\">p.51<\/span><\/li><li class=\"q spoken\">“You guys don’t know anything. Horikita is hands down better than Kushida, anyway.”<span class=\"pg\">p.51<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I mean, if it was any other guy, she’d probably turn them down. But if you were her boyfriend, then it’d be okay, right? Then she’d show you a secret side that no one else gets to see.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> AK&#x27;s frame on the speech: he &quot;crossed his arms and nodded, boasting about his personal preferences&quot; — he reads Horikita&#x27;s coldness as a stage of courtship rather than a refusal, which is exactly the non-recognition she named on p.45.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> The three of them run a rivalry about who gets a girlfriend while his own suspension clock runs down; Yamauchi&#x27;s &quot;But the Horikita of your dreams seems to have tossed you aside, Sudou&quot; lands, and he answers &quot;Well, I guess so. Damn it! Now I feel all depressed.&quot;<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p46-1\">← Before: Ch.3 §3.1: he cannot accept that her refusal has a reason<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p74-1\">→ After: Ch.4 §4.1: he never claimed a witness, and nobody had understood that<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p74-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 4  4 1  he never claimed a witness  and nobody had understood that  what happened today  did you make any progress    he comes to the conference at ak s room the morning after being told tuesday is the deadline  the sentence that quietly invalidates three days of searching   huh  i never said there was someone there  i said that it felt like someone was there  while the group works he plays a phone basketball game and celebrates   after he won the match  he struck a victory pose    ak s title for it   i think the game was called generation of miracles or something  his temper keeps ike from saying what ike thinks   even though sudou couldn t really help  ike and yamauchi still appeared disgruntled at the sight of him  however  they concealed their dissatisfaction  probably because they were scared of sudou s counterattack   did you decide to help out  i m super glad you re here    to horikita  five minutes after she refused him in the cafeteria  ak notes he  was happiest to see her  his one piece of sharp thinking in the chapter  wasted on a name   so you re saying that there s a high probability that this sakura  or kokura  or whoever is the witness    ak   a sharp observation  something a fool would be unlikely to say   did you really do this for me  after all  and  after she denies it   umm  but still  the point is that you saved us  right   yeah  i m happy there s a witness  but who s sakura  do you know her  and  diagonally ahead to the right  i can t remember at all  i m sure there s someone there  though   what a tsundere     sudou wore a happy smile  chuckling and scratching his nose with his finger  after horikita leaves again  ak s correction   she wasn t tsun and she wasn t dere  she was a non tsun  non dere  he has the sense to see the witness is hostile to him and says so before anyone else   why is a gloomy girl like her my witness  this sucks  she doesn t want to help me at all   i know  if she were planning to say something  she would have  she restrained herself  because she s an adult   don t make jokes  i m innocent  innocent  i hit them  but it was out of self defense   what the hell  you guys  didn t you say that you d help me    as ike gives up aloud and the class lets him   why do i have to suffer like this  you bunch of useless jerks  koenji s line about his  ugly  life ends the argument with a kicked desk   suddenly  there was a huge crashing sound  a desk flew through the air and splintered on the ground after being kicked  everyone froze  sudou  silent and intense  walked over to kouenji   bring it on  i ll smash your face in and take you down a peg  he is stopped by hirata rather than by reason and leaves by force   sudou glared at kouenji and left the classroom  slamming the door on his way out  his whole defence is a feeling he cannot evidence and a story he told so loosely that the class built three days of work on a misreading of it  his violence stays available on demand and is the only thing in the chapter that reliably changes the room","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p74-1\"><h3><span class=\"ttl\">Ch.4 §4.1: he never claimed a witness, and nobody had understood that<\/span><span class=\"meta\">Y1V2 · p.74–82<\/span><\/h3><p class=\"setup\">While the group works he plays a phone basketball game and celebrates: &quot;After he won the match, he struck a victory pose.&quot; — AK&#x27;s title for it: &quot;I think the game was called Generation of Miracles or something.&quot; His temper keeps Ike from saying what Ike thinks: &quot;Even though Sudou couldn’t really help, Ike and Yamauchi still appeared disgruntled at the sight of him. However, they concealed their dissatisfaction, probably because they were scared of Sudou’s counterattack.&quot; He has the sense to see the witness is hostile to him and says so before anyone else: “Why is a gloomy girl like her my witness? This sucks. She doesn’t want to help me at all.” Kōenji&#x27;s line about his &quot;ugly&quot; life ends the argument with a kicked desk: &quot;Suddenly, there was a huge crashing sound. A desk flew through the air and splintered on the ground after being kicked. Everyone froze. Sudou, silent and intense, walked over to Kouenji.&quot; He is stopped by Hirata rather than by reason and leaves by force: &quot;Sudou glared at Kouenji and left the classroom, slamming the door on his way out.&quot;<\/p><ul class=\"lines\"><li class=\"q spoken\">“What happened today? Did you make any progress?” — he comes to the conference at AK&#x27;s room the morning after being told Tuesday is the deadline.<span class=\"pg\">p.74<\/span><\/li><li class=\"q spoken\">The sentence that quietly invalidates three days of searching: “Huh? I never said there was someone there. I said that it felt like someone was there.”<span class=\"pg\">p.74<\/span><\/li><li class=\"q spoken\">“Did you decide to help out? I’m super glad you’re here.” — to Horikita, five minutes after she refused him in the cafeteria; AK notes he &quot;was happiest to see her&quot;.<span class=\"pg\">p.76<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> His one piece of sharp thinking in the chapter, wasted on a name: “So you’re saying that there’s a high probability that this Sakura, or Kokura, or whoever is the witness?” — AK: &quot;A sharp observation, something a fool would be unlikely to say.&quot;<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you really do this for me, after all?!” and, after she denies it, “Umm. But still, the point is that you saved us, right?”<span class=\"pg\">p.78<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. I’m happy there’s a witness, but who’s Sakura? Do you know her?” and “Diagonally ahead to the right? I can’t remember at all. I’m sure there’s someone there, though.”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What a tsundere.” — &quot;Sudou wore a happy smile, chuckling and scratching his nose with his finger,&quot; after Horikita leaves again; AK&#x27;s correction: &quot;She wasn’t tsun and she wasn’t dere... She was a non-tsun, non-dere.&quot;<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know. If she were planning to say something, she would have. She restrained herself, because she’s an adult.”<span class=\"pg\">p.90<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t make jokes. I’m innocent. Innocent! I hit them, but it was out of self-defense.”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell, you guys? Didn’t you say that you’d help me?” — as Ike gives up aloud and the class lets him.<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why do I have to suffer like this? You bunch of useless jerks!”<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Bring it on. I’ll smash your face in and take you down a peg,”<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> His whole defence is a feeling he cannot evidence and a story he told so loosely that the class built three days of work on a misreading of it; his violence stays available on demand and is the only thing in the chapter that reliably changes the room.<span class=\"pg\">p.74–93<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p51-1\">← Before: Ch.3 §3.1: the Horikita fantasy, stated in front of the class<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p146-1\">→ After: Ch.4 §4.10: the witness is secured for him, in a mall, without him<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p146-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 4  4 10  the witness is secured for him  in a mall  without him the obstacle the whole class failed to move for three weeks clears while he is not in the room   in her own words  sakura told us that she was the witness  what she is promised to him for   thank you  sakura san  i m sure sudou kun will be really happy  by the close of chapter 4 he has a witness  obtained by kushida and ayanokoji over a camera repair  he never asks sakura anything  and the volume does not show him learning that she saw it  the pattern the volume settles  other people s social labour is what saves him  and he is only ever told about it afterwards  as good news","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p146-1\"><h3><span class=\"ttl\">Ch.4 §4.10: the witness is secured for him, in a mall, without him<\/span><span class=\"meta\">Y1V2 · p.146<\/span><\/h3><p class=\"setup\">The obstacle the whole class failed to move for three weeks clears while he is not in the room: &quot;In her own words, Sakura told us that she was the witness.&quot;<\/p><ul class=\"lines\"><li class=\"q spoken\">What she is promised to him for: &quot;Thank you, Sakura-san. I’m sure Sudou-kun will be really happy.&quot;<span class=\"pg\">p.146<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> By the close of Chapter 4 he has a witness, obtained by Kushida and Ayanokōji over a camera repair; he never asks Sakura anything, and the volume does not show him learning that she saw it.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The pattern the volume settles: other people&#x27;s social labour is what saves him, and he is only ever told about it afterwards, as good news.<span class=\"pg\">p.90–146<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p74-1\">← Before: Ch.4 §4.1: he never claimed a witness, and nobody had understood that<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p165-1\">→ After: Ch.5 §5.2–5.3: told he will be there, and certain of the outcome<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p165-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 5  5 2 5 3  told he will be there  and certain of the outcome he is not in the faculty room  chabashira says the school will inform him   we ll tell sudou that he will be participating in the deliberation  lunch strategy session  he and kushida both turn to horikita for a verdict   of course we will  it s obvious that i was set up  i m definitely innocent  right   hey  horikita  what do you think   but we have a witness who knows i m innocent  and the other guys were real jerks in the past  that should be enough  right  those guys are bad news   sudou  completely blind to his own shortcomings  arrogantly crossed his legs and nodded in agreement with himself","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p165-1\"><h3><span class=\"ttl\">Ch.5 §5.2–5.3: told he will be there, and certain of the outcome<\/span><span class=\"meta\">Y1V2 · p.165–167<\/span><\/h3><p class=\"setup\">Lunch strategy session; he and Kushida both turn to Horikita for a verdict.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Of course we will. It’s obvious that I was set up. I’m definitely innocent. Right?&quot;<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\">&quot;Hey, Horikita. What do you think?&quot;<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\">&quot;But we have a witness who knows I’m innocent, and the other guys were real jerks in the past. That should be enough, right? Those guys are bad news.&quot;<span class=\"pg\">p.167<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He is not in the faculty room; Chabashira says the school will inform him: &quot;we’ll tell Sudou that he will be participating in the deliberation.&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> &quot;Sudou, completely blind to his own shortcomings, arrogantly crossed his legs and nodded in agreement with himself.&quot;<span class=\"pg\">p.167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p146-1\">← Before: Ch.4 §4.10: the witness is secured for him, in a mall, without him<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p191-1\">→ After: Ch.6 open: the fighter who asks for honesty<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p191-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 6 open  the fighter who asks for honesty class d s room before the hearing  he closes his eyes and folds his arms  as if mentally preparing himself  then opens them and asks horikita to say whatever she has to say now   yeah  i m good  i was born ready   you might call me a complete idiot and make fun of me  but i m me  if you have something you want to say  say it now   ugh  you always act so high and mighty  lady  the bickering is affection in his idiom  the narrator notes he would have refused horikita s help outright if he truly hated her  kushida s send off    do your best  horikita san  sudou kun    is answered by sudou pumping his fist to show resolve","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p191-1\"><h3><span class=\"ttl\">Ch.6 open: the fighter who asks for honesty<\/span><span class=\"meta\">Y1V2 · p.191<\/span><\/h3><p class=\"setup\">Class D’s room before the hearing; he closes his eyes and folds his arms &quot;as if mentally preparing himself,&quot; then opens them and asks Horikita to say whatever she has to say now.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yeah… I’m good. I was born ready.&quot;<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">&quot;You might call me a complete idiot and make fun of me, but I’m me. If you have something you want to say, say it now.&quot;<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">&quot;Ugh, you always act so high and mighty, lady.&quot;<span class=\"pg\">p.191<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The bickering is affection in his idiom; the narrator notes he would have refused Horikita’s help outright if he truly hated her.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kushida’s send-off — &quot;Do your best, Horikita-san. Sudou-kun.&quot; — is answered by Sudou pumping his fist to show resolve.<span class=\"pg\">p.191<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p165-1\">← Before: Ch.5 §5.2–5.3: told he will be there, and certain of the outcome<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p194-1\">→ After: Ch.6 §6.1: his account, and the traps in it<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p194-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"sudou-ken","q":"sudo ken ch 6  6 1  his account  and the traps in it  what those guys said was a lie  i was the one that got called over to the special building   that day  after practice  komiya and kondou asked me to go to the special building  honestly  i thought it was kind of annoying  but i also thought it might ve been because they were always hostile towards me  so  i went to meet them   don t screw with me  komiya  you were the one who called me  you jerk  irritated  he strikes the desk   immediate silence followed   not one bit of what komiya said was true  those guys are just jealous of my talent  when i practice  they constantly get in my way  that s the truth   that s a lie  they attacked first  it was self defense  his temper supplies the other side s best evidence  the veins on his forehead and the desk strike are read by the room as confirmation of violence   w wait  i can t accept that  it s just because those guys were a bunch of wimps   b but  hey  i was fighting against three people  three people  the wimps line hands sakagami the question that nearly ends the case   whether overwhelming force against weaker opponents can be self defence","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p194-1\"><h3><span class=\"ttl\">Ch.6 §6.1: his account, and the traps in it<\/span><span class=\"meta\">Y1V2 · p.194–196<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;What those guys said was a lie. I was the one that got called over to the special building,&quot;<span class=\"pg\">p.194<\/span><\/li><li class=\"q spoken\">&quot;That day, after practice, Komiya and Kondou asked me to go to the special building. Honestly, I thought it was kind of annoying, but I also thought it might’ve been because they were always hostile towards me. So, I went to meet…<span class=\"pg\">p.194<\/span><\/li><li class=\"q spoken\">&quot;Don’t screw with me, Komiya! You were the one who called me, you jerk!&quot;<span class=\"pg\">p.194<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That day, after practice, Komiya and Kondou asked me to go to the special building. Honestly, I thought it was kind of annoying, but I also thought it might’ve been because they were always hostile towards me. So, I went to meet them.&quot;<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Irritated, he strikes the desk; &quot;Immediate silence followed.&quot;<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Not one bit of what Komiya said was true. Those guys are just jealous of my talent. When I practice, they constantly get in my way. That’s the truth.&quot;<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That’s a lie. They attacked first. It was self-defense.&quot;<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> His temper supplies the other side’s best evidence: the veins on his forehead and the desk strike are read by the room as confirmation of violence.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;W-wait! I can’t accept that! It’s just because those guys were a bunch of wimps!&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;B-but, hey. I was fighting against three people! Three people!&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> The wimps line hands Sakagami the question that nearly ends the case — whether overwhelming force against weaker opponents can be self-defence.<span class=\"pg\">p.196<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p191-1\">← Before: Ch.6 open: the fighter who asks for honesty<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p205-1\">→ After: Ch.6 §6.1: the compromise he refuses<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p205-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"sudou-ken","q":"sudo ken ch 6  6 1  the compromise he refuses  you jerk  he stands ready to fly out of his chair  then grabs his own arms and pins himself down  the restraint is new and deliberate  the same anger that struck the desk at p 195 is now turned on himself   don t screw around  this isn t a joke   horikita   h hey  the bellow is his only answer to her closing statement  and he cannot tell that it is a performance  after she refuses to sit   sudou s clearly irritated bellow  fills the silence  he still does not understand the reversal until she states it","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p205-1\"><h3><span class=\"ttl\">Ch.6 §6.1: the compromise he refuses<\/span><span class=\"meta\">Y1V2 · p.205–208<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;You jerk!&quot;<span class=\"pg\">p.205<\/span><\/li><li class=\"q spoken\">&quot;Don’t screw around! This isn’t a joke!&quot;<span class=\"pg\">p.205<\/span><\/li><li class=\"q spoken\">&quot;Horikita!&quot;<span class=\"pg\">p.207<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> He stands ready to fly out of his chair, then grabs his own arms and pins himself down.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The restraint is new and deliberate: the same anger that struck the desk at p.195 is now turned on himself.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;H-hey!&quot;<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The bellow is his only answer to her closing statement, and he cannot tell that it is a performance.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After she refuses to sit, &quot;Sudou’s clearly irritated bellow&quot; fills the silence; he still does not understand the reversal until she states it.<span class=\"pg\">p.207<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p194-1\">← Before: Ch.6 §6.1: his account, and the traps in it<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p210-1\">→ After: Ch.6 §6.1: after the hearing<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p210-1","v":"y1v2","y":1,"o":2,"k":"","w":"sudou-ken","q":"sudo ken ch 6  6 1  after the hearing he leaves the student council room behind horikita without a recorded line  the chapter gives him no scene with sakura after the testimony he did not defend","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p210-1\"><h3><span class=\"ttl\">Ch.6 §6.1: after the hearing<\/span><span class=\"meta\">Y1V2 · p.210<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He leaves the student council room behind Horikita without a recorded line; the chapter gives him no scene with Sakura after the testimony he did not defend.<span class=\"pg\">p.210<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p205-1\">← Before: Ch.6 §6.1: the compromise he refuses<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p242-1\">→ After: Ch.7 §7.5: waiting for the retrial to start<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p242-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"sudou-ken","q":"sudo ken ch 7  7 5  waiting for the retrial to start he arrives ten minutes before deliberation with horikita  nervous about the verdict they walked into   oh jeez  i m so nervous  how about you  horikita   huh  don t screw around  i didn t do anything   wait  i don t get it  why are you guys just withdrawing your complaint like that   horikita  horikita pulls him down into his seat mid question and shuts him up","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p242-1\"><h3><span class=\"ttl\">Ch.7 §7.5: waiting for the retrial to start<\/span><span class=\"meta\">Y1V2 · p.242–245<\/span><\/h3><p class=\"setup\">He arrives ten minutes before deliberation with Horikita, nervous about the verdict they walked into.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Oh jeez, I’m so nervous. How about you, Horikita?&quot;<span class=\"pg\">p.242<\/span><\/li><li class=\"q spoken\">&quot;Huh? Don’t screw around. I didn’t do anything,&quot;<span class=\"pg\">p.245<\/span><\/li><li class=\"q spoken\">&quot;Wait. I don’t get it. Why are you guys just withdrawing your complaint like that?&quot;<span class=\"pg\">p.245<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Horikita?&quot;<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Horikita pulls him down into his seat mid-question and shuts him up.<span class=\"pg\">p.245<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p210-1\">← Before: Ch.6 §6.1: after the hearing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p246-1\">→ After: Ch.7 §7.5–7.6: the lecture, the apology, the party<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v2-p246-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"sudou-ken","q":"sudo ken ch 7  7 5 7 6  the lecture  the apology  the party dissatisfied but nodding  the suspension is gone and his club activities restart that day   he he  well  of course    to  i m glad  sudou   yeah    after chabashira tells him the incident happened because of his behavior  that s    on being told horikita will eventually leave him  i understand  if i hadn t acted that way in the first place  then i wouldn t have hit those guys  it wouldn t have been such a big deal  i knew that  somewhere   i always fought all i wanted for my own satisfaction  but it s not like that anymore  i m a class d student  and my personal actions affect the entire class  now i ve experienced that firsthand   i won t cause problems again  sensei  horikita   tch    when chabashira rejects the promise as too casual  y yeah    on hearing that horikita has not abandoned him  wh what does that mean   well  i m gonna get going  i have club activities  see you later  horikita  he leaves smiling  as if he just shaken off something heavy   man  i don t understand what happened  but horikita did something for me  right   well  i gotta head to my club  we should have a party tonight  the page marks the apology as his first penitent words  while insisting he is still himself  a person can t change in one day","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v2-p246-1\"><h3><span class=\"ttl\">Ch.7 §7.5–7.6: the lecture, the apology, the party<\/span><span class=\"meta\">Y1V2 · p.246–252<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;He he. Well, of course!&quot; — to &quot;I’m glad, Sudou&quot;<span class=\"pg\">p.246<\/span><\/li><li class=\"q spoken\">&quot;Yeah…&quot; — after Chabashira tells him the incident happened because of his behavior<span class=\"pg\">p.246<\/span><\/li><li class=\"q spoken\">&quot;That’s…&quot; — on being told Horikita will eventually leave him<span class=\"pg\">p.247<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Dissatisfied but nodding: the suspension is gone and his club activities restart that day.<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I understand… If I hadn’t acted that way in the first place, then I wouldn’t have hit those guys. It wouldn’t have been such a big deal. I knew that, somewhere.&quot;<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I always fought all I wanted for my own satisfaction. But it’s not like that anymore… I’m a Class D student, and my personal actions affect the entire class. Now I’ve experienced that firsthand…&quot;<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I won’t cause problems again, sensei. Horikita.&quot;<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Tch!&quot; — when Chabashira rejects the promise as too casual<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Y-yeah…&quot; — on hearing that Horikita has not abandoned him<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Wh-what does that mean?!&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, I’m gonna get going. I have club activities. See you later, Horikita.&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He leaves smiling &quot;as if he just shaken off something heavy.&quot;<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Man, I don’t understand what happened, but Horikita did something for me. Right?&quot;<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, I gotta head to my club. We should have a party tonight.&quot;<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Position<\/span> The page marks the apology as his first penitent words, while insisting he is still himself: a person can’t change in one day.<span class=\"pg\">p.247<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v2-p242-1\">← Before: Ch.7 §7.5: waiting for the retrial to start<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p13-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"horikita-suzune ike-kanji sudou-ken","q":"sudo ken ch 2  2 0  the cruise  the class a shove  and the name practice deck of the liner  survives the joke about his expulsion scoring final   with my skills  there was nothing to worry about  didn t i tell you i d prove myself  and it d be easy  answers a class a shove with intimidation and is talked down by the situation  not by fear    a fistfight didn t break out  evidence that he was perhaps growing up  forces ayanokoji into imaginary horikita practice so he can ask for her first name  the look  really creeped me out  puts ike in a chokehold for the gyaru performance","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p13-1\"><h3><span class=\"ttl\">Ch.2 §2.0: the cruise, the Class A shove, and the name practice<\/span><span class=\"meta\">Y1V3 · p.13–19<\/span><\/h3><p class=\"setup\">Deck of the liner; survives the joke about his expulsion-scoring final.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“With my skills, there was nothing to worry about. Didn’t I tell you I’d prove myself, and it’d be easy?”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Answers a Class A shove with intimidation and is talked down by the situation, not by fear — &quot;A fistfight didn’t break out, evidence that he was perhaps growing up.&quot;<span class=\"pg\">p.15–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Forces Ayanokōji into imaginary-Horikita practice so he can ask for her first name; the look &quot;really creeped me out.&quot;<span class=\"pg\">p.17–19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Puts Ike in a chokehold for the gyaru performance.<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p33-1\">→ After: Ch.2 §2.1–§2.5: the toilet, the leader card, and a first calm intervention<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p33-1","v":"y1v3","y":1,"o":3,"k":"","w":"horikita-suzune shinohara-satsuki ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 2  2 1 2 5  the toilet  the leader card  and a first calm intervention opens the cardboard toilet crisis by needing it before the explanation is finished  steps forward to take the leader role in her place    you don t want to do it though  right  don t make her do it  i can do it in her place    and the offer is what triggers her acceptance  chides her in an unusually calm tone    i know i ve caused trouble for the class  that s what i m saying    and offers the boiling compromise nobody expected from him  self aware about his own record   if you keep antagonizing people with trivial crap  eventually it s gonna come back to bite you  refuses the branch run flatly and goes swimming instead","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p33-1\"><h3><span class=\"ttl\">Ch.2 §2.1–§2.5: the toilet, the leader card, and a first calm intervention<\/span><span class=\"meta\">Y1V3 · p.33, p.66–74<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Opens the cardboard-toilet crisis by needing it before the explanation is finished.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Steps forward to take the leader role in her place — &quot;You don’t want to do it though, right? Don’t make her do it. I can do it in her place.&quot; — and the offer is what triggers her acceptance.<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Chides her in an unusually calm tone — &quot;I know I’ve caused trouble for the class. That’s what I’m saying.&quot; — and offers the boiling compromise nobody expected from him.<span class=\"pg\">p.68–69<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Self-aware about his own record: &quot;If you keep antagonizing people with trivial crap, eventually it’s gonna come back to bite you.&quot;<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Refuses the branch run flatly and goes swimming instead.<span class=\"pg\">p.74<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p13-1\">← Before: Ch.2 §2.0: the cruise, the Class A shove, and the name practice<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p152-1\">→ After: Ch.5 §5.2: the invitation that fails<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p152-1","v":"y1v3","y":1,"o":3,"k":"action spoken","w":"horikita-suzune ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 5  5 2  the invitation that fails closing ceremonies  the moment the bell rings he goes after horikita with a summer invitation   why  did you do something   yeah  you re not good or bad  you live a plain  boring  steady life   sarcastic  i didn t mean to  did it feel like it  the banter before the invitation turns untagged after he is named as the first speaker  the lines are recorded by turn   hey  horikita  um  well  since it s summer vacation are you free  maybe we can hang out a little  the vacation invite   movies or shopping   meets a flat refusal  she sees no reason for the invitation at all   well  because it s summer vacation  you know  it d be too bad if you didn t have fun  we can watch movies or go shopping   wh why  why are you being so obtuse   well  it s just like that  you know  right  guys invite girls out when it s a holiday   hey  where are you going   can you wait just a little  just a bit   you re gonna watch me do battle  be my wingman  grabs ayanokoji s wrists in both meaty hands and will not let go until he promises to watch the battle  recruits him as wingman for a pitch that loses its audience when chabashira s call pulls him away   damn  guess it was useless after all  well  guess i ll go do club stuff  watches horikita leave without a glance back   dumbfounded   and falls back on club practice","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p152-1\"><h3><span class=\"ttl\">Ch.5 §5.2: the invitation that fails<\/span><span class=\"meta\">Y1V3 · p.152–153<\/span><\/h3><p class=\"setup\">Closing ceremonies: the moment the bell rings he goes after Horikita with a summer invitation.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Why? Did you do something?”<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\">“Yeah. You’re not good or bad. You live a plain, boring, steady life.”<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\">“Sarcastic? I didn’t mean to. Did it feel like it?”<span class=\"pg\">p.152<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The banter before the invitation turns untagged after he is named as the first speaker; the lines are recorded by turn.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, Horikita. Um, well, since it’s summer vacation…are you free? Maybe we can hang out a little.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The vacation invite — movies or shopping — meets a flat refusal; she sees no reason for the invitation at all.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, because it’s summer vacation, you know? It’d be too bad if you didn’t have fun. We can watch movies or go shopping.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “‘Wh-why’? Why are you being so obtuse?”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it’s just like that, you know? Right? Guys invite girls out when it’s a holiday…”<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey! Where are you going?”<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you wait just a little? Just a bit?”<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re gonna watch me do battle. Be my wingman.”<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Grabs Ayanokōji’s wrists in both meaty hands and will not let go until he promises to watch the battle.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recruits him as wingman for a pitch that loses its audience when Chabashira’s call pulls him away.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Damn. Guess it was useless after all. Well, guess I’ll go do club stuff.”<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Watches Horikita leave without a glance back — dumbfounded — and falls back on club practice.<span class=\"pg\">p.153<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p33-1\">← Before: Ch.2 §2.1–§2.5: the toilet, the leader card, and a first calm intervention<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p159-1\">→ After: Ch.6: the tent<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p159-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 6  the tent stumbles out of the tent at shinohara s call  swearing he is exhausted   what the hell  god  i m so goddamn tired","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p159-1\"><h3><span class=\"ttl\">Ch.6: the tent<\/span><span class=\"meta\">Y1V3 · p.159–170<\/span><\/h3><p class=\"setup\">Stumbles out of the tent at Shinohara’s call, swearing he is exhausted.<\/p><ul class=\"lines\"><li class=\"q spoken\">“What the hell? God, I’m so goddamn tired…”<span class=\"pg\">p.159<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p152-1\">← Before: Ch.5 §5.2: the invitation that fails<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p171-1\">→ After: Ch.6 §6.1: volunteering<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p171-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"sudou-ken","q":"sudo ken ch 6  6 1  volunteering raises his hand for the girls  physical work as soon as hirata asks for another boy   wait  if it s physical work  i ll do it","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p171-1\"><h3><span class=\"ttl\">Ch.6 §6.1: volunteering<\/span><span class=\"meta\">Y1V3 · p.171–178<\/span><\/h3><p class=\"setup\">Raises his hand for the girls’ physical work as soon as Hirata asks for another boy.<\/p><ul class=\"lines\"><li class=\"q spoken\">“Wait. If it’s physical work, I’ll do it!”<span class=\"pg\">p.174<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p159-1\">← Before: Ch.6: the tent<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p191-1\">→ After: Ch.6 §6.4: the river<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p191-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"ayanokouji-kiyotaka hirata-yousuke sudou-ken","q":"sudo ken ch 6  6 4  the river wakes ayanokoji by sleeping with his legs across his face  calling for suzune in his sleep   suzune i can t hold back anymore  mistakes him for someone else in his sleep and lashes out when woken   gah  shut up  the hell  ayanokouji  don t wake me up like that   no  ike kun  sudou kun  i want you two to continue fishing  we don t have enough time to instruct the other students how to do it  kept on fishing with ike through the last day","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p191-1\"><h3><span class=\"ttl\">Ch.6 §6.4: the river<\/span><span class=\"meta\">Y1V3 · p.191–199<\/span><\/h3><p class=\"setup\">Wakes Ayanokōji by sleeping with his legs across his face, calling for Suzune in his sleep.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Suzune…I can’t hold back anymore…”<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">“Gah, shut up… The hell? Ayanokouji, don’t wake me up like that.”<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “No. Ike-kun, Sudou-kun, I want you two to continue fishing. We don’t have enough time to instruct the other students how to do it.”<span class=\"pg\">p.192<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Mistakes him for someone else in his sleep and lashes out when woken.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Kept on fishing with Ike through the last day.<span class=\"pg\">p.192<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p171-1\">← Before: Ch.6 §6.1: volunteering<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p211-1\">→ After: Ch.6 §6.7: reading Hirata’s collapse<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p211-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"hirata-yousuke sudou-ken","q":"sudo ken ch 6  6 7  reading hirata s collapse comes through the rain to ask after hirata  and delivers the chapter s sharpest read of him   ayanokouji  is hirata okay   looks like he s in shock  i suppose it s probably because of all these things going wrong one after the other   you know  in junior high there was this rich kid honor student  he had a lot of really heavy responsibilities  y know  anyway  he took so much on himself that one day  he ended up having a breakdown  after that  his class became a complete mess   you think there are signs of that with hirata   well  saying he s gonna have a breakdown would be an exaggeration  but i think there s danger there  reads the danger of a breakdown in hirata before anyone else   the narration calls the diagnosis surprisingly accurate  the one who names the risk he is carrying  horikita s own history with him   his class c assault and the trial that followed   is what makes her hesitate before using force against ibuki  named once more when horikita measures herself against him and the others   i can t be dumber than sudou kun and the others","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p211-1\"><h3><span class=\"ttl\">Ch.6 §6.7: reading Hirata’s collapse<\/span><span class=\"meta\">Y1V3 · p.211<\/span><\/h3><p class=\"setup\">Comes through the rain to ask after Hirata, and delivers the chapter’s sharpest read of him.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ayanokouji. Is Hirata okay?”<span class=\"pg\">p.211<\/span><\/li><li class=\"q spoken\">“Looks like he’s in shock. I suppose it’s probably because of all these things going wrong one after the other.”<span class=\"pg\">p.211<\/span><\/li><li class=\"q spoken\">“You know, in junior high there was this rich kid honor student. He had a lot of really heavy responsibilities, y’know? Anyway, he took so much on himself that one day, he ended up having a breakdown. After that, his class became…”<span class=\"pg\">p.211<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You know, in junior high there was this rich kid honor student. He had a lot of really heavy responsibilities, y’know? Anyway, he took so much on himself that one day, he ended up having a breakdown. After that, his class became a complete mess.”<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You think there are signs of that with Hirata?”<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, saying he’s gonna have a breakdown would be an exaggeration, but I think there’s danger there.”<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reads the danger of a breakdown in Hirata before anyone else — the narration calls the diagnosis surprisingly accurate.<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> The one who names the risk he is carrying.<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Backstory<\/span> Horikita’s own history with him — his Class C assault and the trial that followed — is what makes her hesitate before using force against Ibuki.<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Named once more when Horikita measures herself against him and the others: “I can’t be dumber than Sudou-kun and the others.”<span class=\"pg\">p.229<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p191-1\">← Before: Ch.6 §6.4: the river<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p240-1\">→ After: Ch.7: the results and the first name<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v3-p240-1","v":"y1v3","y":1,"o":3,"k":"action spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru horikita-suzune sudou-ken","q":"sudo ken ch 7  the results and the first name opens the chapter at the rest area by asking how close ayanokoji and horikita are  then lives through ryuuen s provocation and the results announcement on the beach   ayanokouji  you work pretty well with horikita  don t you  how close are you  really  the question that opens the chapter   how close he and horikita really are   even that makes me jealous  though  i still ain t her friend   but didn t horikita acknowledge you a little bit this time  runs untagged between sudou s lines   it could be either sudou or ayanokoji speaking   and is left out as a chapter attribution gap   i sure hope so  she still hasn t called me by my first name  after all   wait  what did you say  what are you talking about   oh  hey there  sycophants  what happened to suzune   i know you ve been chasing suzune s ass  we were together before  you know   what a stupid thing to say  huh  pick up your own trash  jerk   but picking up garbage seems like the perfect task for garbage  trampled the cup ryuuen threw at ayanokoji s feet  then collars him over the suzune talk   the next time you say something stupid  i ll kill you  sudou growled   what are you doing  and  huh  what s with you  getting all excited by yourself  huh  run untagged around sudou s tagged threat and are left out as chapter attribution gaps   that s what we should be saying to you class c people  you used up all of your points  right  don t make us laugh   so you re going to expose a class leader  untagged  the narration then has hirata and ayanokoji holding their faces still while sudou alone looks shocked  so the question is placed as his   hold on a minute  what are you talking about  huh  i if you re telling the truth  then   bwah ha ha ha  hey  check it out  you guys have zero points after all   yahoo  we did it  in your face  raises a middle finger and sticks out his tongue at ryuuen on the way to the boat   s suzune  are you feeling better now  asks after her recovery  is granted the first name for one line  then has it withdrawn   don t worry about it   by the way  sudou kun  don t just go around calling me by my first name without permission  understand   y y yeah","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v3-p240-1\"><h3><span class=\"ttl\">Ch.7: the results and the first name<\/span><span class=\"meta\">Y1V3 · p.240–246<\/span><\/h3><p class=\"setup\">Opens the chapter at the rest area by asking how close Ayanokōji and Horikita are, then lives through Ryuuen’s provocation and the results announcement on the beach.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ayanokouji. You work pretty well with Horikita, don’t you? How close are you, really?”<span class=\"pg\">p.240<\/span><\/li><li class=\"q spoken\">“Even that makes me jealous, though. I still ain’t her friend.”<span class=\"pg\">p.240<\/span><\/li><li class=\"q spoken\">“I sure hope so. She still hasn’t called me by my first name, after all.”<span class=\"pg\">p.240<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The question that opens the chapter — how close he and Horikita really are.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “But didn’t Horikita acknowledge you a little bit this time?” runs untagged between Sudou’s lines — it could be either Sudou or Ayanokōji speaking — and is left out as a chapter attribution gap.<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, what did you say? What are you talking about?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, hey there, sycophants. What happened to Suzune?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know you’ve been chasing Suzune’s ass. We were together before, you know.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What a stupid thing to say. Huh? Pick up your own trash, jerk.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But picking up garbage seems like the perfect task for garbage.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Trampled the cup Ryuuen threw at Ayanokōji’s feet, then collars him over the Suzune talk.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The next time you say something stupid, I’ll kill you,” Sudou growled.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “What are you doing?” and “Huh? What’s with you? Getting all excited by yourself, huh?” run untagged around Sudou’s tagged threat and are left out as chapter attribution gaps.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s what we should be saying to you Class C people. You used up all of your points, right? Don’t make us laugh.”<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’re going to expose a class leader?”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Untagged; the narration then has Hirata and Ayanokōji holding their faces still while Sudou alone looks shocked, so the question is placed as his.<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hold on a minute. What are you talking about, huh?! I-If you’re telling the truth, then…”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Bwah ha ha ha! Hey, check it out! You guys have zero points after all!”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yahoo! We did it! In your face!”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Raises a middle finger and sticks out his tongue at Ryuuen on the way to the boat.<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “S-Suzune. Are you feeling better now?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Asks after her recovery, is granted the first name for one line, then has it withdrawn.<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t worry about it.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way, Sudou-kun. Don’t just go around calling me by my first name without permission. Understand?”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-y-yeah.”<span class=\"pg\">p.246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v3-p211-1\">← Before: Ch.6 §6.7: reading Hirata’s collapse<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4-p13-1","v":"y1v4","y":1,"o":4,"k":"","w":"sudou-ken","q":"sudo ken ch 2  2 0  a passing mention in hirata s inventory named once at the cabin lunch  in hirata s list of the people who treat ayanokoji as a friend  hirata s line carries him   you have sudou kun and the guys  and horikita san","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4-p13-1\"><h3><span class=\"ttl\">Ch.2 §2.0: a passing mention in Hirata’s inventory<\/span><span class=\"meta\">Y1V4 · p.13<\/span><\/h3><p class=\"setup\">Named once at the cabin lunch, in Hirata’s list of the people who treat Ayanokōji as a friend.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Hirata’s line carries him: “you have Sudou-kun and the guys, and Horikita-san.”<span class=\"pg\">p.13<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p43-1\">→ After: Ch.2 §2.3: a passing mention in the comprehension sketch<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4-p43-1","v":"y1v4","y":1,"o":4,"k":"","w":"sudou-ken","q":"sudo ken ch 2  2 3  a passing mention in the comprehension sketch named once as a contrast while the narration sizes up karuizawa s refusal to listen  the comparison  her problem  wasn t that she scored poorly on tests like sudou or ike    unlike them  she simply won t listen","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4-p43-1\"><h3><span class=\"ttl\">Ch.2 §2.3: a passing mention in the comprehension sketch<\/span><span class=\"meta\">Y1V4 · p.43<\/span><\/h3><p class=\"setup\">Named once as a contrast while the narration sizes up Karuizawa’s refusal to listen.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The comparison: her problem “wasn’t that she scored poorly on tests like Sudou or Ike” — unlike them, she simply won’t listen.<span class=\"pg\">p.43<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p13-1\">← Before: Ch.2 §2.0: a passing mention in Hirata’s inventory<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p100-1\">→ After: Ch.3: on Sakura’s Cow roster<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4-p100-1","v":"y1v4","y":1,"o":4,"k":"","w":"sudou-ken","q":"sudo ken ch 3  on sakura s cow roster the cow roster and ayanokoji s sympathy both name him as one of the class d boys sakura is stuck with  listed as sudou ken in class d with sakura  ike  and matsushita  ayanokoji rules him and ike out as contacts for sakura","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4-p100-1\"><h3><span class=\"ttl\">Ch.3: on Sakura’s Cow roster<\/span><span class=\"meta\">Y1V4 · p.100–101<\/span><\/h3><p class=\"setup\">The Cow roster and Ayanokōji’s sympathy both name him as one of the Class D boys Sakura is stuck with.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Listed as Sudou Ken in Class D with Sakura, Ike, and Matsushita.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji rules him and Ike out as contacts for Sakura.<span class=\"pg\">p.101<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p43-1\">← Before: Ch.2 §2.3: a passing mention in the comprehension sketch<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p183-1\">→ After: Ch.4 §4.5–4.7: the Cow name and the warning<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4-p183-1","v":"y1v4","y":1,"o":4,"k":"","w":"sakura-airi karuizawa-kei sudou-ken","q":"sudo ken ch 4  4 5 4 7  the cow name and the warning named in sakura s cow group vip uncertainty  then again as ayanokoji s example that eye for eye brings a school investigation   i m not sure about sudou kun or  um  the others    the only cow roster name she speaks  the sudou precedent cited to her   you should know from what happened with sudou that this isn t a simple matter  no scene presence in either range  both rows are other people speaking his name","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4-p183-1\"><h3><span class=\"ttl\">Ch.4 §4.5–4.7: the Cow name and the warning<\/span><span class=\"meta\">Y1V4 · p.183, 195<\/span><\/h3><p class=\"setup\">Named in Sakura’s Cow-group VIP uncertainty, then again as Ayanokōji’s example that eye-for-eye brings a school investigation.<\/p><p class=\"with\">with <a href=\"sakura-airi.html\">Sakura Airi<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> “I’m not sure about Sudou-kun or, um, the others” — the only Cow-roster name she speaks.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> The Sudou precedent cited to her: “You should know from what happened with Sudou that this isn’t a simple matter.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No scene presence in either range; both rows are other people speaking his name.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p100-1\">← Before: Ch.3: on Sakura’s Cow roster<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p235-1\">→ After: Ch.5 §5.3: the sixth wheel<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4-p235-1","v":"y1v4","y":1,"o":4,"k":"spoken","w":"horikita-suzune ryuuen-kakeru sudou-ken","q":"sudo ken ch 5  5 3  the sixth wheel trails horikita into the cafe as the attached ghost  is told to get lost twice  stays anyway  chides ryuuen about the last results  and is ignored through the kushida reveal   i just thought you might be nervous  i came to check on you  she calls him a ghost  spat  get lost  and shuts him up   he sinks back obediently   aw  come on  don t say that  horikita  i just thought you might be nervous during the test  so i was worried about you  that s why i came to check on you   h hey  don t say that  i gave this test everything i had  you know   i was just one step behind  that s all  looks like someone else sent the email before me  he muttered  the email he claims he almost sent   one step behind  someone beat him to it  then the chair grab and  you wouldn t cut out a classmate  right   come on  it s fine  isn t it  i m just going to listen  you wouldn t cut out a classmate  right  rises to threaten on sight  chides him about the last results loss  then is snapped down by horikita s  sudou kun  be quiet   isn t that just a coincidence  asked sudou  apparently  from sudou s perspective  everything was a coincidence   don t you hang all over horikita  roared sudou   and i remember that the last time they announced results  you were acting all high and mighty  but then you lost big  sudou chided  pointing a finger at ryuuen and laughing   surprisingly docile  after the snap   the roar is all  he sinks back on command  present for the whole results scene  no role in the deductions   the row marks the unusual crowd","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4-p235-1\"><h3><span class=\"ttl\">Ch.5 §5.3: the sixth wheel<\/span><span class=\"meta\">Y1V4 · p.235–241<\/span><\/h3><p class=\"setup\">Trails Horikita into the café as the attached ghost, is told to get lost twice, stays anyway, chides Ryuuen about the last results, and is ignored through the Kushida reveal.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Aw, come on. Don’t say that, Horikita. I just thought you might be nervous during the test, so I was worried about you. That’s why I came to check on you.”<span class=\"pg\">p.235<\/span><\/li><li class=\"q spoken\">“H-hey, don’t say that. I gave this test everything I had, you know.”<span class=\"pg\">p.235<\/span><\/li><li class=\"q spoken\">“I was just one step behind, that’s all. Looks like someone else sent the email before me,” he muttered.<span class=\"pg\">p.235<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I just thought you might be nervous… I came to check on you”; she calls him a ghost, spat “Get lost,” and shuts him up — he sinks back obediently.<span class=\"pg\">p.235-238<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The email he claims he almost sent — one step behind, someone beat him to it; then the chair-grab and “You wouldn’t cut out a classmate, right?”<span class=\"pg\">p.235-236<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Come on. It’s fine, isn’t it? I’m just going to listen. You wouldn’t cut out a classmate, right?”<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Rises to threaten on sight, chides him about the last results loss, then is snapped down by Horikita’s “Sudou-kun, be quiet.”<span class=\"pg\">p.237-238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t that just a coincidence?” asked Sudou. Apparently, from Sudou’s perspective, everything was a coincidence.<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you hang all over Horikita!” roared Sudou.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And I remember that the last time they announced results, you were acting all high and mighty. But then you lost big,” Sudou chided, pointing a finger at Ryuuen and laughing.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “Surprisingly docile” after the snap — the roar is all; he sinks back on command.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Present for the whole results scene; no role in the deductions — the row marks the unusual crowd.<span class=\"pg\">p.235-241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4-p183-1\">← Before: Ch.4 §4.5–4.7: the Cow name and the warning<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p11-1","v":"y1v4.5","y":1,"o":5,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 2  the fortune teller call tournament rest day  chicken tender small talk pivots to a crazy accurate fortune teller at keyaki mall  and to his real objective  receives a 100 000 point transfer from ayanokoji just before calling  plans the outing like a drill   9 30 arrival for a 10 00 start to beat the line   and pays his own way   let s check it out together  the tournament  the only first year to play in the big game  and he scored  the team lost   i made sure to delete the data before heading back  sudou said  the outing is for her  he demands the invitation and brushes off the odds with  there s nothing to worry about  after the failed invite his reply is one line   then forget about it    ayanokoji existed only as a means to reach horikita","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p11-1\"><h3><span class=\"ttl\">Ch.2: the fortune-teller call<\/span><span class=\"meta\">Y1V4.5 · p.11–14<\/span><\/h3><p class=\"setup\">Tournament rest day: chicken-tender small talk pivots to a crazy-accurate fortune-teller at Keyaki Mall, and to his real objective.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I made sure to delete the data before heading back,” Sudou said.<span class=\"pg\">p.13<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Position<\/span> Receives a 100,000-point transfer from Ayanokōji just before calling.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Plans the outing like a drill — 9:30 arrival for a 10:00 start to beat the line — and pays his own way: “Let’s check it out together.”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> The tournament: the only first-year to play in the big game, and he scored; the team lost.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The outing is for her: he demands the invitation and brushes off the odds with “There’s nothing to worry about.”<span class=\"pg\">p.13–14<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After the failed invite his reply is one line: “Then forget about it” — Ayanokōji existed only as a means to reach Horikita.<span class=\"pg\">p.17<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p15-1\">→ After: Ch.2: passing mentions<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p15-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"sudou-ken","q":"sudo ken ch 2  passing mentions his angry face is what keeps ayanokoji on the phone call  a real possibility is weighed while the image of sudou lingers  his insistence on inviting horikita is the reason the plan takes shape  ibuki is compared to him while he angles for time with horikita  first sudou  now ibuki  the queue talk makes him its opening topic","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p15-1\"><h3><span class=\"ttl\">Ch.2: passing mentions<\/span><span class=\"meta\">Y1V4.5 · p.15, 19–21<\/span><\/h3><p class=\"setup\">His angry face is what keeps Ayanokōji on the phone call.<\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> A real possibility is weighed while the image of Sudou lingers.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> His insistence on inviting Horikita is the reason the plan takes shape.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ibuki is compared to him while he angles for time with Horikita.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> First Sudou, now Ibuki: the queue talk makes him its opening topic.<span class=\"pg\">p.21<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p11-1\">← Before: Ch.2: the fortune-teller call<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p28-1\">→ After: Ch.2: a passing mention in the partner list<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p28-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"sudou-ken","q":"sudo ken ch 2  a passing mention in the partner list named once among the guys who would not spend their last summer days on a paired reading  the list   the guys  like sudou  ike  and yamauchi    and he had already washed his hands of the outing","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p28-1\"><h3><span class=\"ttl\">Ch.2: a passing mention in the partner list<\/span><span class=\"meta\">Y1V4.5 · p.28<\/span><\/h3><p class=\"setup\">Named once among the guys who would not spend their last summer days on a paired reading.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The list: “the guys, like Sudou, Ike, and Yamauchi” — and he had already washed his hands of the outing.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p15-1\">← Before: Ch.2: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p48-1\">→ After: Ch.2: a passing mention in Katsuragi’s thanks<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p48-1","v":"y1v4.5","y":1,"o":5,"k":"spoken","w":"katsuragi-kouhei sudou-ken","q":"sudo ken ch 2  a passing mention in katsuragi s thanks named in katsuragi s thanks at the elevator   the plan s other half   sudou performed brilliantly  katsuragi wants it passed on  he is very appreciative  and asks ayanokoji to tell him once again","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p48-1\"><h3><span class=\"ttl\">Ch.2: a passing mention in Katsuragi’s thanks<\/span><span class=\"meta\">Y1V4.5 · p.48<\/span><\/h3><p class=\"setup\">Named in Katsuragi’s thanks at the elevator — the plan’s other half.<\/p><p class=\"with\">with <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “Sudou performed brilliantly.”<span class=\"pg\">p.48<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Katsuragi wants it passed on: he is very appreciative, and asks Ayanokōji to tell him once again.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p28-1\">← Before: Ch.2: a passing mention in the partner list<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p51-1\">→ After: Ch.3: his share of the points<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p51-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"ike-kanji sudou-ken","q":"sudo ken ch 3  his share of the points sudou is absent from the shopping trip  but his share of the gift points rides along with the boys  ak cites sudou s entrustment to stop the bickering between ike and yamauchi","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p51-1\"><h3><span class=\"ttl\">Ch.3: his share of the points<\/span><span class=\"meta\">Y1V4.5 · p.51<\/span><\/h3><p class=\"setup\">Sudou is absent from the shopping trip, but his share of the gift points rides along with the boys.<\/p><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> AK cites Sudou&#x27;s entrustment to stop the bickering between Ike and Yamauchi.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p48-1\">← Before: Ch.2: a passing mention in Katsuragi’s thanks<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p60-1\">→ After: Ch.3: passing mentions<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p60-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"sudou-ken","q":"sudo ken ch 3  passing mentions the birthday hunt turnout includes him after his club activities  an earlier incident involving sudou of class d is raised in the council room talk","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p60-1\"><h3><span class=\"ttl\">Ch.3: passing mentions<\/span><span class=\"meta\">Y1V4.5 · p.60, 93<\/span><\/h3><p class=\"setup\">The birthday-hunt turnout includes him after his club activities.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> An earlier incident involving Sudou of Class D is raised in the council-room talk.<span class=\"pg\">p.93<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p51-1\">← Before: Ch.3: his share of the points<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p62-1\">→ After: Ch.3: jealousy as strategy<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p62-1","v":"y1v4.5","y":1,"o":5,"k":"spoken","w":"horikita-suzune ike-kanji katsuragi-kouhei kushida-kikyou sudou-ken","q":"sudo ken ch 3  jealousy as strategy in ak s room sudou snaps at the horikita suggestion and demands suzune s birthday   when is suzune s birthday   you re worthless  he takes the february 15 date as a win   snagged some good info   sounds like i ve snagged some good info  he keeps ike in a headlock mid conversation and forgets to let go   just because we ll probably lose to him doesn t mean we don t have a chance of winning   in basketball  you can use plays that are just barely allowed   a strong desire for victory is what really matters  he frames stopping katsuragi s gift as a play just barely allowed   if katsuragi giving a present to some girl will bring them closer  then we gotta stop him from doing it  kushida s ban shuts the plan down  sudou has tournament practice as cover  his basketball tournament is thursday  he claims no free time until after it   you gotta investigate   should i force you  the threat of a headlock is enough to make ak accept the job","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p62-1\"><h3><span class=\"ttl\">Ch.3: jealousy as strategy<\/span><span class=\"meta\">Y1V4.5 · p.62–66<\/span><\/h3><p class=\"setup\">In AK&#x27;s room Sudou snaps at the Horikita suggestion and demands Suzune&#x27;s birthday.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“When is Suzune’s birthday?”<span class=\"pg\">p.62<\/span><\/li><li class=\"q spoken\">“You’re worthless,”<span class=\"pg\">p.62<\/span><\/li><li class=\"q spoken\">“Sounds like I’ve snagged some good info,”<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He takes the February 15 date as a win: “snagged some good info.”<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> He keeps Ike in a headlock mid-conversation and forgets to let go.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just because we’ll probably lose to him doesn’t mean we don’t have a chance of winning!”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In basketball, you can use plays that are just barely allowed.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A strong desire for victory is what really matters.”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> He frames stopping Katsuragi&#x27;s gift as a play just barely allowed.<span class=\"pg\">p.64–65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Katsuragi giving a present to some girl will bring them closer, then we gotta stop him from doing it,”<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Kushida&#x27;s ban shuts the plan down; Sudou has tournament practice as cover.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Position<\/span> His basketball tournament is Thursday; he claims no free time until after it.<span class=\"pg\">p.65<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You gotta investigate,”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Should I force you?”<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> The threat of a headlock is enough to make AK accept the job.<span class=\"pg\">p.66<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p60-1\">← Before: Ch.3: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p98-1\">→ After: Ch.3: the 100,000-point run<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p98-1","v":"y1v4.5","y":1,"o":5,"k":"spoken","w":"katsuragi-kouhei ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 3  the 100 000 point run fresh from club  sudou is pitched the package job and rejects it flatly   seriously  who in their right mind would want to do something like that   besides  i ain t obliged to listen to a request from baldy over here  he lays out the tournament inspection sequence   bags in the morning  phones confiscated  lockers watched  no cross school talk  the 100 000 point offer stiffens him  betrayal fear from class c surfaces   what am i gonna do if you decide to betray me  20 000 advance now  80 000 on success  routed through ak as insurance   i guess i m someone who ll take that risk  katsuragi s lingering doubt annoys him  the one asking for help suspects him   katsuragi s the one who came asking for help  and now he doubts me  he calls ak a surprisingly shady guy for the third party phone trick   you know  you re a surprisingly shady guy  he executes perfectly  bag check passed  gift mailed  video sent and deleted","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p98-1\"><h3><span class=\"ttl\">Ch.3: the 100,000-point run<\/span><span class=\"meta\">Y1V4.5 · p.98–104<\/span><\/h3><p class=\"setup\">Fresh from club, Sudou is pitched the package job and rejects it flatly.<\/p><p class=\"with\">with <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Seriously, who in their right mind would want to do something like that?”<span class=\"pg\">p.98<\/span><\/li><li class=\"q spoken\">“Besides, I ain’t obliged to listen to a request from baldy over here,”<span class=\"pg\">p.98<\/span><\/li><li class=\"q spoken\">“What am I gonna do if you decide to betray me?”<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> He lays out the tournament inspection sequence — bags in the morning, phones confiscated, lockers watched, no cross-school talk.<span class=\"pg\">p.98–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> The 100,000-point offer stiffens him; betrayal fear from Class C surfaces.<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Position<\/span> 20,000 advance now, 80,000 on success, routed through AK as insurance.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess I’m someone who’ll take that risk,”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Katsuragi&#x27;s lingering doubt annoys him: the one asking for help suspects him.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Katsuragi’s the one who came asking for help, and now he doubts me?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He calls AK a surprisingly shady guy for the third-party phone trick.<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You know, you’re a surprisingly shady guy.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Result<\/span> He executes perfectly: bag check passed, gift mailed, video sent and deleted.<span class=\"pg\">p.104<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p62-1\">← Before: Ch.3: jealousy as strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p119-1\">→ After: Ch.4: a passing mention<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p119-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"horikita-suzune sudou-ken","q":"sudo ken ch 4  a passing mention named with ike as a possible source of water for the stuck bottle  horikita passes on his water too  lumping him with ike as careless with drinks","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p119-1\"><h3><span class=\"ttl\">Ch.4: a passing mention<\/span><span class=\"meta\">Y1V4.5 · p.119<\/span><\/h3><p class=\"setup\">Named with Ike as a possible source of water for the stuck bottle.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita passes on his water too, lumping him with Ike as careless with drinks.<span class=\"pg\">p.119<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p98-1\">← Before: Ch.3: the 100,000-point run<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p160-1\">→ After: Ch.6: passing mentions<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p160-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"sudou-ken","q":"sudo ken ch 6  passing mentions he is named in the four guy outing announcement  he remarks that the others are fired up over something  the object of his admiration is the same student ayanokoji is watching  his name heads the group whose stomachs grumble at the food stands  the earlier rescue from expulsion is raised in the argument over whether he would be gotten rid of  he and yamauchi want shaved ice at the stands  he looks anxious alongside ike and yamauchi","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p160-1\"><h3><span class=\"ttl\">Ch.6: passing mentions<\/span><span class=\"meta\">Y1V4.5 · p.160, 177–178, 190, 194, 200, 203<\/span><\/h3><p class=\"setup\">He is named in the four-guy outing announcement.<\/p><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He remarks that the others are fired up over something.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The object of his admiration is the same student Ayanokōji is watching.<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> His name heads the group whose stomachs grumble at the food stands.<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The earlier rescue from expulsion is raised in the argument over whether he would be gotten rid of.<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He and Yamauchi want shaved ice at the stands.<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He looks anxious alongside Ike and Yamauchi.<span class=\"pg\">p.203<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p119-1\">← Before: Ch.4: a passing mention<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p163-1\">→ After: Ch.6: the keeper<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p163-1","v":"y1v4.5","y":1,"o":5,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 6  the keeper he joins the youth crusade and makes his attendance conditional on suzune   yeah  i want to make the most of my youth  too   if suzune is going  then i m in   you re my friend  right  he oversleeps from club exhaustion and doesn t answer the phone   got way too exhausted from all my club stuff   not really   i think about 3 000 points or so   but lots of second and third years have gotten tens of thousands of points  so i can t get too cocky yet   i m gonna try to do way more in the second semester and onward  he headlocks ike and yamauchi in the locker room and smashes their foreheads together   you guys are causing too much ruckus   if you re a man  you gotta make a girl fall for you  he won t let the others see suzune defenseless   his stated rule is that a man must make a girl fall for him  he stays at horikita s side while the others fall in line behind the girls","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p163-1\"><h3><span class=\"ttl\">Ch.6: the keeper<\/span><span class=\"meta\">Y1V4.5 · p.163–175<\/span><\/h3><p class=\"setup\">He joins the youth crusade and makes his attendance conditional on Suzune.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yeah, I want to make the most of my youth, too!”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\">“If Suzune is going, then I’m in.”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\">“You’re my friend, right?”<span class=\"pg\">p.164<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> He oversleeps from club exhaustion and doesn&#x27;t answer the phone.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Got way too exhausted from all my club stuff,”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not really,”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think about 3,000 points or so,”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But lots of second and third years have gotten tens of thousands of points, so I can’t get too cocky yet.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m gonna try to do way more in the second semester and onward,”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> He headlocks Ike and Yamauchi in the locker room and smashes their foreheads together.<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You guys are causing too much ruckus!”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re a man, you gotta make a girl fall for you,”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> He won&#x27;t let the others see Suzune defenseless — his stated rule is that a man must make a girl fall for him.<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> He stays at Horikita&#x27;s side while the others fall in line behind the girls.<span class=\"pg\">p.175<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p160-1\">← Before: Ch.6: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p183-1\">→ After: Ch.6: the volleyball wall<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p183-1","v":"y1v4.5","y":1,"o":5,"k":"action spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 6  the volleyball wall sudou carries class d s volleyball team with raw power the narration compares to nagumo s  then knocks yamauchi out for the death sentence   leave this to me  suzune   i ll knock those meatheads down  shouted sudou   basketball s like all other sports  he applies an upperclassman s basketball aphorism to pool volleyball  and he defines meathead as a brain grown too big from studying too much   kept as printed  his opening spike is too fast for ichinose to return in the water  the text puts his power greater than or equal to nagumo s  he covers the weak side  intercepts balls meant for ayanokoji  and starts calling the shots for the team   it s pathetic that the girls are more useful than you  said sudou   even if it s bad  it s okay  as long as you get the ball up  her praise after the win makes him smile smugly  ichinose reports his reputation has already reached other classes  after the match he delivers the promised death sentence to yamauchi outside the pool","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p183-1\"><h3><span class=\"ttl\">Ch.6: the volleyball wall<\/span><span class=\"meta\">Y1V4.5 · p.183–189<\/span><\/h3><p class=\"setup\">Sudou carries Class D&#x27;s volleyball team with raw power the narration compares to Nagumo&#x27;s, then knocks Yamauchi out for the death sentence.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Leave this to me, Suzune.”<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\">“I&#x27;ll knock those meatheads down!” shouted Sudou.<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\">“Basketball&#x27;s like all other sports.”<span class=\"pg\">p.184<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He applies an upperclassman&#x27;s basketball aphorism to pool volleyball, and he defines meathead as a brain grown too big from studying too much — kept as printed.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> His opening spike is too fast for Ichinose to return in the water; the text puts his power greater than or equal to Nagumo&#x27;s.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> He covers the weak side, intercepts balls meant for Ayanokōji, and starts calling the shots for the team.<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s pathetic that the girls are more useful than you!” said Sudou.<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if it&#x27;s bad, it&#x27;s okay, as long as you get the ball up!”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her praise after the win makes him smile smugly; Ichinose reports his reputation has already reached other classes.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After the match he delivers the promised death sentence to Yamauchi outside the pool.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p163-1\">← Before: Ch.6: the keeper<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p205-1\">→ After: Ch.7: the enforcer<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v4_5-p205-1","v":"y1v4.5","y":1,"o":5,"k":"action spoken","w":"sudou-ken","q":"sudo ken ch 7  the enforcer he stays silent through the pitch  then joins as the plan s enforcer   the one who clears the vent and guards the wall   i ll make a decision after i hear you out   the next thing you buy should be carpet  dude   someone as useless as you shouldn t hoard points  he shot back   it s dangerous  like ayanokouji says  he is assigned the role of threatening anyone who gets near the vent  trading on his reputation   that s  fightin  and violence are two different things  answered sudou  the claim on suzune s body is left to him by the translation s group narration  the line itself carries no speaker tag   you guys don t got any right to see suzune s naked body  he kicks ayanokoji s door while waiting  then relaxes in the room as if it were his own   you re late  ayanokouji  sudou  his patience gone  kicked my door   ain t no guy alive who s not excited about seeing a naked woman","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v4_5-p205-1\"><h3><span class=\"ttl\">Ch.7: the enforcer<\/span><span class=\"meta\">Y1V4.5 · p.205–223<\/span><\/h3><p class=\"setup\">He stays silent through the pitch, then joins as the plan’s enforcer — the one who clears the vent and guards the wall.<\/p><ul class=\"lines\"><li class=\"q spoken\">“I’ll make a decision after I hear you out.”<span class=\"pg\">p.205<\/span><\/li><li class=\"q spoken\">“The next thing you buy should be carpet, dude.”<span class=\"pg\">p.206<\/span><\/li><li class=\"q spoken\">“Someone as useless as you shouldn’t hoard points,” he shot back.<span class=\"pg\">p.206<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s dangerous, like Ayanokouji says.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> He is assigned the role of threatening anyone who gets near the vent, trading on his reputation.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s… Fightin’ and violence are two different things,” answered Sudou.<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The claim on Suzune’s body is left to him by the translation’s group narration; the line itself carries no speaker tag.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You guys don’t got any right to see Suzune’s naked body.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> He kicks Ayanokōji’s door while waiting, then relaxes in the room as if it were his own.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re late, Ayanokouji!” Sudou, his patience gone, kicked my door.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ain’t no guy alive who’s not excited about seeing a naked woman.”<span class=\"pg\">p.223<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v4_5-p183-1\">← Before: Ch.6: the volleyball wall<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p11-1","v":"y1v5","y":1,"o":6,"k":"inner","w":"sudou-ken","q":"sudo ken ch 1  the soliloquy volume cold open  sudou s first person soliloquy alone with his backstory  no other character appears  and p 12 carries no prose   to be completely honest  i ain t really a capable person  his mother abandoned the family to go into the nightclub business  his father toiled as a janitor with a permanently hunched back  and the sight of it sickened him   being the idiot i am  i decided to give up on studyin  and go into sports    he chose getting stronger over studying and frames it as his own idea  not a defeat  solo sports first   tennis and pingpong  good but never top tier   then basketball  despite not being a team player he got seriously into it  kept improving  and was recommended to a high school with one of the best basketball teams in the entire country  the pulled recommendation defines his self read   that was when i really understood the painful truth  i was trash  born from trash  chose this school for what it promised   that was why i chose this school    free  and able to guarantee even his future  blank short scan page  running footer only  no prose to cite","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p11-1\"><h3><span class=\"ttl\">Ch.1: the soliloquy<\/span><span class=\"meta\">Y1V5 · p.11–12<\/span><\/h3><p class=\"setup\">Volume cold open: Sudou’s first-person soliloquy alone with his backstory; no other character appears, and p.12 carries no prose.<\/p><ul class=\"lines\"><li class=\"q inner\">“To be completely honest, I ain’t really a capable person.”<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Fact<\/span> His mother abandoned the family to go into the nightclub business; his father toiled as a janitor with a permanently hunched back, and the sight of it sickened him.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “Being the idiot I am, I decided to give up on studyin’ and go into sports.” — he chose getting stronger over studying and frames it as his own idea, not a defeat.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Solo sports first — tennis and pingpong, good but never top-tier — then basketball: despite not being a team player he got seriously into it, kept improving, and was recommended to a high school with one of the best basketball teams in the entire country.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The pulled recommendation defines his self-read: “That was when I really understood the painful truth: I was trash, born from trash.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Chose this school for what it promised: “That was why I chose this school.” — free, and able to guarantee even his future.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page: running footer only; no prose to cite.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p16-1\">→ After: Ch.2 §2.1: the huddle<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune ike-kanji sudou-ken","q":"sudo ken ch 2  2 1  the huddle named as one of the athletic students fired up by the sports festival   probably the first exam that lets him contribute meaningfully  his athletic ability is the class s read on him before the events are even set  pulls ike and yamauchi to her and opens the strategy huddle   let s figure this out  horikita   class d can win this   if i do that  we ll win    claims every recommended participant event  tells ike flatly that the recommended events belong to people who are good at sports   you re not  kanji  pushes back on her stamina caution   even tired  he moves better than the unathletic guys   and leaves without a decision   but it s better to leave it to me than put forward someone unathletic  right","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p16-1\"><h3><span class=\"ttl\">Ch.2 §2.1: the huddle<\/span><span class=\"meta\">Y1V5 · p.16, 23–25<\/span><\/h3><p class=\"setup\">Named as one of the athletic students fired up by the sports festival — probably the first exam that lets him contribute meaningfully.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Let’s figure this out, Horikita,”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\">“Class D can win this,”<span class=\"pg\">p.24<\/span><\/li><li class=\"q spoken\">“If I do that, we’ll win,” — claims every recommended-participant event.<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> His athletic ability is the class’s read on him before the events are even set.<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pulls Ike and Yamauchi to her and opens the strategy huddle.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Tells Ike flatly that the recommended events belong to people who are good at sports.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not, Kanji,”<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pushes back on her stamina caution — even tired, he moves better than the unathletic guys — and leaves without a decision.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it’s better to leave it to me than put forward someone unathletic, right?”<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p11-1\">← Before: Ch.1: the soliloquy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p39-1\">→ After: Ch.3 §3: The ability camp, then the grip-strength king<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"shinohara-satsuki kouenji-rokusuke ayanokouji-kiyotaka sudou-ken","q":"sudo ken ch 3  3  the ability camp  then the grip strength king sudou argues the ability side of hirata s blackboard and  by p 40  has claimed every recommended competition for himself   if i win  then it s more likely our class wins   i ll do all the events for recommended participants  turns his new leadership on shinohara    if we lose because of you  will you take responsibility  huh  votes horikita   when winners win  we all win  claims every recommended competition and warns the class    i ll participate in every competition  confronts koenji for abstaining   hey  kouenji  ain t you gonna cooperate  posts 82 4 kilograms of grip strength   the highest printed score   and bellows through the test   this is what a real man looks like   it s just  cause i train all the time  taunts koenji for refusing the meter   what  you scared of losing to me or something   maybe  like  around 60    his guess at the average  which ayanokoji uses to stop his own meter at 60 6  despairs at the class s depth   man  i can t rely on a single one of you","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: The ability camp, then the grip-strength king<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><\/h3><p class=\"setup\">Sudou argues the ability side of Hirata’s blackboard and, by p.40, has claimed every recommended competition for himself.<\/p><p class=\"with\">with <a href=\"shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“If I win, then it’s more likely our class wins.”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\">“I’ll do all the events for recommended participants,”<span class=\"pg\">p.40<\/span><\/li><li class=\"q spoken\">“It’s just ’cause I train all the time.”<span class=\"pg\">p.49<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shinohara Satsuki<\/b> Turns his new leadership on Shinohara — “If we lose because of you, will you take responsibility? Huh?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Votes Horikita: “When winners win, we all win.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Claims every recommended competition and warns the class — “I’ll participate in every competition.”<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Confronts Kōenji for abstaining: “Hey, Kouenji. Ain’t you gonna cooperate?”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Posts 82.4 kilograms of grip strength — the highest printed score — and bellows through the test: “This is what a real man looks like.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Taunts Kōenji for refusing the meter: “What? You scared of losing to me or something?”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe, like, around 60?” — his guess at the average, which Ayanokōji uses to stop his own meter at 60.6.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Despairs at the class’s depth: “Man, I can’t rely on a single one of you.”<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p16-1\">← Before: Ch.2 §2.1: the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p54-1\">→ After: Ch.4 §4: The name bet and the leader’s first week<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p54-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune kushida-kikyou kouenji-rokusuke hirata-yousuke ike-kanji sudou-ken","q":"sudo ken ch 4  4  the name bet and the leader s first week sudou arrives mid practice and calls horikita by her first name  starting the chapter s central bet   you have a minute    how the  suzune  address opens   not too long ago  you saved me    why he wants to do things properly   i think i d like to be friends with you  first  accepts the grade wide bar   if i place first in our grade level  i ll call you by your first name  goes  y yeah  when she adds the forever forbidden penalty  unbeatable in the aptitude tests   kushida calls him the sports festival leader  glares at koenji over the untested running question   even so  i dunno what ll happen if he runs  handed the leadership by hirata   would you mind leading our class for this   i ain t really suited to be a leader or anythin   okay  i ll lead our class to victory    living up to her half approval  coaches tug of war by demonstration  beating ike and yamauchi in seconds  and teaches hips over arms   look  i m tellin  you that ain t it    kicks dirt at ike and yamauchi when they botch the pull  thorough with every student who asks  but his rashness keeps undercutting the gentler style a leader needs","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p54-1\"><h3><span class=\"ttl\">Ch.4 §4: The name bet and the leader’s first week<\/span><span class=\"meta\">Y1V5 · p.54–67<\/span><\/h3><p class=\"setup\">Sudou arrives mid-practice and calls Horikita by her first name, starting the chapter’s central bet.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “You have a minute?” — how the “Suzune” address opens.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Not too long ago, you saved me.” — why he wants to do things properly.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I think I’d like to be friends with you, first.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Accepts the grade-wide bar: “If I place first in our grade level, I’ll call you by your first name,”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Goes “Y-yeah” when she adds the forever-forbidden penalty.<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Unbeatable in the aptitude tests — Kushida calls him the sports festival leader.<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Glares at Kōenji over the untested running question: “Even so, I dunno what’ll happen if he runs.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Handed the leadership by Hirata: “Would you mind leading our class for this?”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I ain’t really suited to be a leader or anythin’…”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Okay! I’ll lead our class to victory,” — living up to her half-approval.<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Coaches tug-of-war by demonstration, beating Ike and Yamauchi in seconds, and teaches hips over arms.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> “Look, I’m tellin’ you that ain’t it!” — kicks dirt at Ike and Yamauchi when they botch the pull.<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Thorough with every student who asks, but his rashness keeps undercutting the gentler style a leader needs.<span class=\"pg\">p.59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p39-1\">← Before: Ch.3 §3: The ability camp, then the grip-strength king<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p68-1\">→ After: Ch.5 §5: Noodles, first names, and the anchor he gives up<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p68-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 5  5  noodles  first names  and the anchor he gives up sudou spends saturday morning in ayanokoji s room with ike and yamauchi  cup noodles in hand  talking about horikita   what flavor did you get   trade with me  please  an untagged classmate asks  do you plan on telling horikita  and sudou answers  huh  the hell is this about   that depends on how the festival goes    on making a move after the bet   there ain t none of the first years better than me at sports   let s talk about my future with suzune  given the relay anchor  then pulled aside when horikita asks for it  not convinced   it s just  y know  the anchor position goes to the fastest team member   i ain t convinced  this ain t like you  horikita  yields once the brother reason is on the table    i don t mind handin  it over to you","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p68-1\"><h3><span class=\"ttl\">Ch.5 §5: Noodles, first names, and the anchor he gives up<\/span><span class=\"meta\">Y1V5 · p.68–85<\/span><\/h3><p class=\"setup\">Sudou spends Saturday morning in Ayanokōji’s room with Ike and Yamauchi, cup noodles in hand, talking about Horikita.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What flavor did you get?”<span class=\"pg\">p.72<\/span><\/li><li class=\"q spoken\">“Trade with me, please?”<span class=\"pg\">p.72<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> An untagged classmate asks “Do you plan on telling Horikita?” and Sudou answers “Huh? The hell is this about?”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “That depends on how the festival goes.” — on making a move after the bet.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “there ain’t none of the first years better than me at sports,”<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “Let’s talk about my future with Suzune,”<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Given the relay anchor, then pulled aside when Horikita asks for it.<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Not convinced: “It’s just, y’know, the anchor position goes to the fastest team member.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> “I ain’t convinced. This ain’t like you, Horikita,”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Yields once the brother reason is on the table — “I don’t mind handin’ it over to you,”<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p54-1\">← Before: Ch.4 §4: The name bet and the leader’s first week<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p87-1\">→ After: Ch.6 §6: the leader’s festival<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p87-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"kouenji-rokusuke ryuuen-kakeru hirata-yousuke horikita-suzune sudou-ken","q":"sudo ken ch 6  6  the leader s festival sudou lines up for the first year boys  100 metre dash in group one and carries class d s hopes on his speed  wins the 100 metre dash by a landslide  the professor  in the same heat  comes in last  storms the cottage to confront koenji for sitting out  his punch is caught in koenji s palm  and hirata walks him back to camp   don t give me that bull crap   next time  i m seriously going to punch that jerk  he huffed   stress relief  said sudou    headlocks ike as horikita s heat is about to start  threatens to beat him for skipping the event  then sulks that he will punch him next time  as capture the flag offense he charges the flag line alone  yamada punches him in the stomach and ryuuen stomps his back as the flag falls   just how many of you are gonna come after me   you re useless   that was foul play   the next time i run into him  i m gonna lay him out flat  vows to lay ryuuen flat  ayanokoji talks him down by citing the near expulsion fight  accepts hirata s calming hand after the flag falls  though his anger outweighs the pain  pushes the tug of war despite his injured back  after ryuuen s forfeit he charges again and katsuragi holds him back   that s exactly why we can t lose this  sudou said   class b put their biggest dudes up way up in front   with those guys lined up like that  there s no way they ll win  said sudou   i won t accept anything besides victory  takes first in the obstacle course three times in a row  beating shibata in a close finish  then pins ike in a nelson hold for sixth place   still  though  that shibata guy was really fast  said sudou  balls his fists cheering horikita on in the girls  obstacle course  his leadership style is open threats   kick the asses of the people under him   and he admits no one really wants such a leader","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p87-1\"><h3><span class=\"ttl\">Ch.6 §6: the leader’s festival<\/span><span class=\"meta\">Y1V5 · p.87–114<\/span><\/h3><p class=\"setup\">Sudou lines up for the first-year boys’ 100-metre dash in group one and carries Class D’s hopes on his speed.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Don’t give me that bull crap!”<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\">“Next time, I’m seriously going to punch that jerk,” he huffed.<span class=\"pg\">p.91<\/span><\/li><li class=\"q spoken\">“Stress relief,” said Sudou. — headlocks Ike as Horikita’s heat is about to start.<span class=\"pg\">p.91<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Wins the 100-metre dash by a landslide; the Professor, in the same heat, comes in last.<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Storms the cottage to confront Kōenji for sitting out; his punch is caught in Kōenji’s palm, and Hirata walks him back to camp.<span class=\"pg\">p.90–91<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Threatens to beat him for skipping the event, then sulks that he will punch him next time.<span class=\"pg\">p.90–91<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> As capture-the-flag offense he charges the flag line alone; Yamada punches him in the stomach and Ryuuen stomps his back as the flag falls.<span class=\"pg\">p.100–104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just how many of you are gonna come after me?!”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re useless!”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That was foul play!”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The next time I run into him, I’m gonna lay him out flat!”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Vows to lay Ryuuen flat; Ayanokōji talks him down by citing the near-expulsion fight.<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Accepts Hirata’s calming hand after the flag falls, though his anger outweighs the pain.<span class=\"pg\">p.102–104<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Pushes the tug-of-war despite his injured back; after Ryuuen’s forfeit he charges again and Katsuragi holds him back.<span class=\"pg\">p.105–110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s exactly why we can’t lose this,” Sudou said.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Class B put their biggest dudes up way up in front.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “With those guys lined up like that, there’s no way they’ll win,” said Sudou.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t accept anything besides victory!”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Takes first in the obstacle course three times in a row, beating Shibata in a close finish; then pins Ike in a nelson hold for sixth place.<span class=\"pg\">p.111–112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Still, though, that Shibata guy was really fast.” said Sudou.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Balls his fists cheering Horikita on in the girls’ obstacle course.<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> His leadership style is open threats — kick the asses of the people under him — and he admits no one really wants such a leader.<span class=\"pg\">p.110<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p68-1\">← Before: Ch.5 §5: Noodles, first names, and the anchor he gives up<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p115-1\">→ After: Ch.6 §6: first place, bait, and the punch<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p115-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-suzune ryuuen-kakeru yamada-albert yukimura-teruhiko sudou-ken","q":"sudo ken ch 6  6  first place  bait  and the punch sudou runs the boys  three legged with ike  practically carrying him  and takes first  carries ike across the line  hirata and ayanokoji follow with their own first of the day  ike cried in agony as sudou bolted with him  the pair still nabbed first  sudou calls out  go  suzune  during the girls  three legged   the still forbidden first name  safely out of horikita s earshot  cheeks her first name  then volunteers to get class c back for her after the cavalry loss   hey  don t worry  bout it  it was hopeless   leave it to me  i ll get  em back for you  anchors the boys  cavalry at the centre of hirata s unit  smashes through class b  then takes ryuuen s one on one bait and rejects katsuragi s pincer   aim for that shitty ryuuen s head   oh  i remember your name  sudou  bites the one on one offer  threatens katsuragi s unit if he interferes  then loses when the sticky headband kills hirata s grip   fine  don t forget what you just said  ryuuen   stick your nose in this  and i ll bust up your unit  cannot break through yamada  whose strength matches his own  confronts ryuuen over the hair gel  evidence already gone   that s foul play  you slathered your headband with something  storms class c after the provocation stack  shoves hirata aside  and punches him down in front of the class   i m seriously going to beat the crap out of that jerk   shut it  he s the one who should be sorry   i m the leader here  so  listen up  hirata  let s confront ryuuen together   so what if i did  what then   whatever  do what you want  go ahead and lose for all i care  you scum  this sports festival thing can go to hell  walks off toward the dormitory  absent for the rest of the morning half   koenji gone  sudou gone  is cut by yukimura for showboating before the punch lands on hirata instead  peak athlete and worst crisis in one body  three individual wins  then a single swing that removes the class s ace from the board","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p115-1\"><h3><span class=\"ttl\">Ch.6 §6: first place, bait, and the punch<\/span><span class=\"meta\">Y1V5 · p.115–135<\/span><\/h3><p class=\"setup\">Sudou runs the boys’ three-legged with Ike, practically carrying him, and takes first.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"index.html#yamada-albert\">Yamada Albert<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey, don’t worry ’bout it. It was hopeless.”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\">“Leave it to me. I’ll get ’em back for you,”<span class=\"pg\">p.123<\/span><\/li><li class=\"q spoken\">“Aim for that shitty Ryuuen’s head!”<span class=\"pg\">p.124<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Carries Ike across the line; Hirata and Ayanokōji follow with their own first of the day.<span class=\"pg\">p.115–116<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ike cried in agony as Sudou bolted with him; the pair still nabbed first.<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Sudou calls out “Go, Suzune!” during the girls’ three-legged — the still-forbidden first name, safely out of Horikita’s earshot.<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Cheeks her first name, then volunteers to get Class C back for her after the cavalry loss.<span class=\"pg\">p.116, 123<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Anchors the boys’ cavalry at the centre of Hirata’s unit; smashes through Class B, then takes Ryuuen’s one-on-one bait and rejects Katsuragi’s pincer.<span class=\"pg\">p.123–128, §6.8<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, I remember your name. Sudou.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Bites the one-on-one offer, threatens Katsuragi’s unit if he interferes, then loses when the sticky headband kills Hirata’s grip.<span class=\"pg\">p.125–129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine. Don’t forget what you just said, Ryuuen!”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stick your nose in this, and I’ll bust up your unit!”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> Cannot break through Yamada, whose strength matches his own.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Confronts Ryuuen over the hair gel; evidence already gone.<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s foul play! You slathered your headband with something!”<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Storms Class C after the provocation stack, shoves Hirata aside, and punches him down in front of the class.<span class=\"pg\">p.132–134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m seriously going to beat the crap out of that jerk!”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shut it! He’s the one who should be sorry!”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m the leader here! So, listen up, Hirata. Let’s confront Ryuuen together,”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what if I did? What then?”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whatever, do what you want. Go ahead and lose for all I care, you scum. This sports festival thing can go to hell,”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Walks off toward the dormitory; absent for the rest of the morning half — Kōenji gone, Sudou gone.<span class=\"pg\">p.133–135<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Is cut by Yukimura for showboating before the punch lands on Hirata instead.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Peak athlete and worst crisis in one body: three individual wins, then a single swing that removes the class’s ace from the board.<span class=\"pg\">p.115–135<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p87-1\">← Before: Ch.6 §6: the leader’s festival<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p163-1\">→ After: Ch.8 §8.1: the lobby lecture<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p163-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke sudou-ken","q":"sudo ken ch 8  8 1  the lobby lecture sudou sits alone on a dorm lobby sofa after walking out  he expects a scolding and gets horikita s honesty instead  sudou greets her with  horikita    too short for a says row   why are you here  don t tell me you came to persuade me to go back   probably not  guess we re in a lot of trouble right now  huh   and after i carried everyone on my back  that hirata  resents hirata for stopping the rampage  horikita says he should be grateful   you re seriously tryin  to preach to me  give me a break  horikita  i m really pissed  sudou snaps  shut up    too short for a says row   i took the leader job because i thought the sports festival would be easy as pie  i haven t lost to anyone from the other classes   maybe i just wanted to see how it felt for people to pay attention to me and give me some respect   i was born to worthless people  that s why i m worthless  too  blames worthless parents for turning out worthless  horikita rejects the hypothesis   fine  then just brand me worthless  already  go ahead  i don t even care anymore   go back  horikita   do what you want","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p163-1\"><h3><span class=\"ttl\">Ch.8 §8.1: the lobby lecture<\/span><span class=\"meta\">Y1V5 · p.163–167<\/span><\/h3><p class=\"setup\">Sudou sits alone on a dorm lobby sofa after walking out; he expects a scolding and gets Horikita’s honesty instead.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Why are you here? Don’t tell me you came to persuade me to go back?”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\">“Probably not. Guess we’re in a lot of trouble right now, huh?”<span class=\"pg\">p.163<\/span><\/li><li class=\"q spoken\">“And after I carried everyone on my back. That Hirata,”<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Sudou greets her with “Horikita.” — too short for a says row.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Resents Hirata for stopping the rampage; Horikita says he should be grateful.<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re seriously tryin’ to preach to me? Give me a break, Horikita. I’m really pissed,”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Sudou snaps “Shut up!” — too short for a says row.<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I took the leader job because I thought the sports festival would be easy as pie. I haven’t lost to anyone from the other classes.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe I just wanted to see how it felt for people to pay attention to me and give me some respect.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I was born to worthless people. That’s why I’m worthless, too.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Blames worthless parents for turning out worthless; Horikita rejects the hypothesis.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine. Then just brand me worthless, already. Go ahead. I don’t even care anymore,”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Go back, Horikita.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do what you want.”<span class=\"pg\">p.167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p115-1\">← Before: Ch.6 §6: first place, bait, and the punch<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p176-1\">→ After: Ch.8 §8.3: comes back for her<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p176-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu horikita-suzune sudou-ken","q":"sudo ken ch 8  8 3  comes back for her an hour later sudou returns only to see if she is still at the elevator  then agrees to work with her until graduation   did did you seriously wait around here   it s already over  isn t it  the sports festival  i mean   nope  i just came down here to see if you were still hanging around  is all   we ain t got anythin  in common  you and i are way too different   yeah  that prim and proper guy  names the president as prim and proper before learning he is her brother   oh  so  wait  you said something about fighting with him  right   you re not givin  up   that sounds like a painful path to take   ah  what the hell am i feelin  right now  i don t get it  but it s like  i feel like i ve finally had my eyes opened   i ll work with you  horikita  i i feel like someone s finally noticed me outside basketball  accepts her as an ally  first time anyone outside basketball has noticed him","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p176-1\"><h3><span class=\"ttl\">Ch.8 §8.3: comes back for her<\/span><span class=\"meta\">Y1V5 · p.176–179<\/span><\/h3><p class=\"setup\">An hour later Sudou returns only to see if she is still at the elevator, then agrees to work with her until graduation.<\/p><p class=\"with\">with <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Did…did you seriously wait around here?”<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\">“It’s already over, isn’t it? The sports festival, I mean.”<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\">“Nope. I just came down here to see if you were still hanging around, is all.”<span class=\"pg\">p.176<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We ain’t got anythin’ in common. You and I are way too different.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, that prim-and-proper guy?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Names the president as prim-and-proper before learning he is her brother.<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh? So… Wait. You said something about fighting with him, right?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not givin’ up?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That sounds like a painful path to take.”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah. What the hell am I feelin’ right now?! I don’t get it, but it’s like… I feel like I’ve finally had my eyes opened.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll work with you, Horikita. I…I feel like someone’s finally noticed me outside basketball.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Accepts her as an ally; first time anyone outside basketball has noticed him.<span class=\"pg\">p.179<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p163-1\">← Before: Ch.8 §8.1: the lobby lecture<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p181-1\">→ After: Ch.9 §9: the apology and the lead leg<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p181-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke sudou-ken","q":"sudo ken ch 9  9  the apology and the lead leg sudou returns out of breath  bows to the class  apologizes for the hirata punch  and takes the first relay leg   yeah  sorry  my bad  it took way longer to take a dump than i thought   sorry  i punched hirata and crashed our morale because i lost my temper  it s my fault that class d is about to lose   i gotta admit  i did somethin  wrong after doing somethin  wrong  i want to apologize to you  too  kanji   if you haven t decided on a sub for the relay  please let me run  bows for the punch  hirata laughs happily despite the swollen cheek   well  guess we don t got much choice  there ain t any other way for us to win  explosive start  passes eleven people in the first stride and hands off with a fifteen metre lead","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p181-1\"><h3><span class=\"ttl\">Ch.9 §9: the apology and the lead leg<\/span><span class=\"meta\">Y1V5 · p.181–184<\/span><\/h3><p class=\"setup\">Sudou returns out of breath, bows to the class, apologizes for the Hirata punch, and takes the first relay leg.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yeah, sorry. My bad. It took way longer to take a dump than I thought.”<span class=\"pg\">p.181<\/span><\/li><li class=\"q spoken\">“Sorry. I punched Hirata and crashed our morale because I lost my temper. It’s my fault that Class D is about to lose,”<span class=\"pg\">p.181<\/span><\/li><li class=\"q spoken\">“I gotta admit, I did somethin’ wrong after doing somethin’ wrong. I want to apologize to you, too, Kanji,”<span class=\"pg\">p.181<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If you haven’t decided on a sub for the relay, please let me run,”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Bows for the punch; Hirata laughs happily despite the swollen cheek.<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, guess we don’t got much choice. There ain’t any other way for us to win,”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Explosive start: passes eleven people in the first stride and hands off with a fifteen-metre lead.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p176-1\">← Before: Ch.8 §8.3: comes back for her<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p189-1\">→ After: Ch.9 §9.1: MVP loss and the promise<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p189-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune sudou-ken","q":"sudo ken ch 9  9 1  mvp loss and the promise sudou slaps ayanokouji s back after the race  at the scoreboard shibata takes first year mvp and sudou keeps the first name ban   ayanokouji  you really are super fast  dude  whoa  have you been holding back until now   gaaahh  i knew it   yeah  sudou replied   it s unfortunate  but a promise is a promise  i ll call you horikita from now on   it s my punishment  right  i promise  accepts the no violence condition and her granted first name  raises both arms   the sports festival is the best  it s the best  suzune","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p189-1\"><h3><span class=\"ttl\">Ch.9 §9.1: MVP loss and the promise<\/span><span class=\"meta\">Y1V5 · p.189–192<\/span><\/h3><p class=\"setup\">Sudou slaps Ayanokouji’s back after the race; at the scoreboard Shibata takes first-year MVP and Sudou keeps the first-name ban.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ayanokouji! You really are super fast, dude. Whoa! Have you been holding back until now?!”<span class=\"pg\">p.189<\/span><\/li><li class=\"q spoken\">“Gaaahh! I knew it!”<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">“Yeah,” Sudou replied. “It’s unfortunate. But a promise is a promise. I’ll call you Horikita from now on.”<span class=\"pg\">p.191<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s my punishment, right? I promise,”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Accepts the no-violence condition and her granted first name; raises both arms: “The sports festival is the best! It’s the best, Suzune!”<span class=\"pg\">p.192<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p181-1\">← Before: Ch.9 §9: the apology and the lead leg<\/button><\/div><\/article>"}];
